local _runCount = 0
local _runBusy = false
local run = function(func)
	if not _runBusy then
		_runBusy = true
		_runCount = _runCount + 1
		if _runCount % 8 == 0 then
			task.wait()
		end
		local ok, err = pcall(func)
		_runBusy = false
		if not ok then
			warn('[MXTION V4] module failed to load: ' .. tostring(err))
		end
		return
	end
	local ok, err = pcall(func)
	if not ok then
		warn('[MXTION V4] module failed to load: ' .. tostring(err))
	end
end
