		Darker = true,
		Visible = false,
		Function = function()
			if ProjectileAimbot.Enabled and DesirePAHideCursor.Enabled then
				updateCursor()
			end
		end
	})

	DesirePACursorShowGUI = ProjectileAimbot:CreateToggle({
		Name = 'Show on GUI',
		Darker = true,
		Visible = false,
		Function = function()
			if ProjectileAimbot.Enabled and DesirePAHideCursor.Enabled then
				updateCursor()
			end
		end
