	})
	PredictVertical = ProjectileAimbot:CreateSlider({
		Name = 'Vertical',
		Min = 0,
		Max = 300,
		Default = 100,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = "AutoCharge",
		Default = true,
		Function = function(v)
			if skidPAChargePercent and skidPAChargePercent.Object then skidPAChargePercent.Object.Visible = v end
		end
