		Darker = true,
		Visible = false,
		Tooltip = 'auto switches to bows / projectiles to look legit'
	})
	Kits = Killaura:CreateToggle({
		Name = 'Kits',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'use kit ability stuff'
	})
	Arrows = Killaura:CreateToggle({
		Name = 'Arrows',
		Default = true,
		Darker = true,
		Visible = false,
		Tooltip = 'tursn off arrows on projectiles'
	})
	Gloops = Killaura:CreateToggle({
		Name = 'Gloops',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'auto gloops enemy in combat'
	})
	Fireball = Killaura:CreateToggle({
		Name = 'Fireball',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'automatically throws an fireball'
	})
	ArrowCharge = Killaura:CreateSlider({
		Name = 'Charge Rate',
		Suffix = '%',
		Min = 0,
		Max = 100,
		Default = 100,
		Darker = true,
