run(function()
	local JadeAura
	local Targets
	local SlamRange
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Safely locate the Jade Hammer remote
	local function getJadeRemote()
		local success, remote = pcall(function()
			return ReplicatedStorage:FindFirstChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):FindFirstChild("useAbility")
		end)
		return success and remote or nil
	end

	-- Check if target is valid based on selected Targets options
	local function isValidTarget(ent)
		if not ent or ent == entitylib.character then return false end
		if ent.Player and not Targets.Players.Enabled then return false end
		if ent.NPC and not Targets.NPCs.Enabled then return false end
		if ent.Targetable == false then return false end
		return true
	end

	-- Find the closest valid target within Slam Range
	local function getTargetInRange()
		if not entitylib.isAlive then return nil end

		local myPos = entitylib.character.RootPart.Position
		local closestEnt = nil
		local shortestDist = SlamRange.Value

		for _, ent in ipairs(entitylib.List) do
			if isValidTarget(ent) and ent.RootPart then
				local dist = (myPos - ent.RootPart.Position).Magnitude
				if dist <= shortestDist then
					shortestDist = dist
					closestEnt = ent
				end
			end
		end

		return closestEnt
	end

	-- Create module in Blatant category
	local Category = vape.Categories.Blatant

	JadeAura = Category:CreateModule({
		Name = 'JadeAura',
		Function = function(callback)
			if callback then
				JadeAura:Clean(runService.Heartbeat:Connect(function()
					local target = getTargetInRange()
					if target then
						local remote = getJadeRemote()
						if remote then
							pcall(function()
								remote:FireServer("jade_hammer_jump")
							end)
						end
					end
				end))
			end
		end,
		Tooltip = 'Automatically uses Jade Hammer ability when targets enter range.'
	})

	-- Configurable Targets & Range Sliders
	Targets = JadeAura:CreateTargets({
		Players = true,
		NPCs = false,
		Function = function() end
	})

	SlamRange = JadeAura:CreateSlider({
		Name = 'Slam Range',
		Function = function() end,
		Default = 18,
		Min = 0,
		Max = 22,
		Decimal = 10
	})
end)

run(function()
    local ElektraExtender
    local ExtensionSlider
    local InstantToggle

    local netManaged = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged")
    local electricDashRemote = netManaged:FindFirstChild("ElectricDash")
    local tweenTeleportRemote = netManaged:FindFirstChild("TweenTeleport")

    local oldInvoke
    local oldFireSignal

    ElektraExtender = vape.Categories.Kits:CreateModule({
        Name = 'ElektraExtender',
        Function = function(callback)
            if callback then
                -- Hook ElectricDash InvokeServer for range extension
                if electricDashRemote then
                    oldInvoke = hookmetamethod(game, "__namecall", function(self, ...)
                        local args = {...}
                        local method = getnamecallmethod()

                        if self == electricDashRemote and (method == "InvokeServer" or method == "invokeServer") and args[1] then
                            local data = args[1]
                            if data.startCFrame and data.destCFrame then
                                local direction = (data.destCFrame.Position - data.startCFrame.Position).Unit
                                local distance = (data.destCFrame.Position - data.startCFrame.Position).Magnitude + ExtensionSlider.Value
                                
                                local newDestPos = data.startCFrame.Position + (direction * distance)
                                data.destCFrame = CFrame.new(newDestPos) * (data.destCFrame - data.destCFrame.Position)
                            end
                        end

                        return oldInvoke(self, ...)
                    end)
                end

                -- Hook firesignal / client event handling to override tween time BEFORE client receives it
                if firesignal then
                    oldFireSignal = hookfunction(firesignal, function(signal, ...)
                        local args = {...}
                        if InstantToggle.Enabled and signal == tweenTeleportRemote.OnClientEvent and typeof(args[1]) == "table" then
                            args[1].time = 0.1 -- Forces instant execution
                        end
                        return oldFireSignal(signal, unpack(args))
                    end)
                end
            else
                if oldInvoke then
                    hookmetamethod(game, "__namecall", oldInvoke)
                    oldInvoke = nil
                end
                if oldFireSignal then
                    hookfunction(firesignal, oldFireSignal)
                    oldFireSignal = nil
                end
            end
        end,
        Tooltip = 'Extends Elektra dash distance and removes teleport delay'
    })

    ExtensionSlider = ElektraExtender:CreateSlider({
        Name = 'Extra Studs',
        Min = 0,
        Max = 13,
        Default = 5,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
        Tooltip = 'Additional distance added to your ElectricDash (Max 13)'
    })

    InstantToggle = ElektraExtender:CreateToggle({
        Name = 'Instant Teleport',
        Default = true,
        Tooltip = 'Forces TweenTeleport duration from 0.3s to 0.01s'
    })
end)

run(function()
	local MemoryFixer
	local Sync
	local Interval
	local Notify
	local signals = {'Heartbeat', 'PostSimulation', 'PreAnimation', 'PreRender', 'PreSimulation', 'RenderStepped', 'Stepped'}
	
	local function clean()
		if not getconnections or not getfunctionhash or not isexecutorclosure then
			return 0
		end
	
		local removed, seen = 0, {}
		for _, v in signals do
			for _, connection in getconnections(runService[v]) do
				if connection.Function and not connection.ForeignState and isexecutorclosure(connection.Function) then
					local hash = v..getfunctionhash(connection.Function)
					if seen[hash] then
						connection:Disconnect()
						removed += 1
					else
						seen[hash] = true
					end
				end
			end
		end
	
		if Sync.Enabled then
			for _, event in bedwars.SyncEvents do
				if typeof(event) == 'table' and typeof(event.entries) == 'table' then
					table.clear(seen)
					for i, entry in event.entries do
						local callback = entry.callbackInfo and entry.callbackInfo.callback
						if callback and isexecutorclosure(callback) then
							local hash = getfunctionhash(callback)
							if seen[hash] then
								event.entries[i] = nil
								event.isSorted = false
								removed += 1
							else
								seen[hash] = true
							end
						end
					end
				end
			end
		end
	
		return removed
	end
	
	MemoryFixer = vape.Categories.Utility:CreateModule({
		Name = 'MemoryFixer',
		Function = function(callback)
			if callback then
				task.spawn(function()
					repeat
						local removed = clean()
						if Notify.Enabled and removed > 0 then
							notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
						end
						task.wait(Interval.Value)
					until not MemoryFixer.Enabled
				end)
			end
		end,
		Tooltip = 'Drops the duplicate loops and listeners an older injection left connected'
	})
	Sync = MemoryFixer:CreateToggle({
		Name = 'Sync events',
		Default = true,
		Tooltip = 'Also prunes duplicate bedwars sync event listeners, the ones that survive a reinject'
	})
	Interval = MemoryFixer:CreateSlider({
		Name = 'Interval',
		Min = 5,
		Max = 300,
		Default = 30,
		Suffix = 'seconds'
	})
	Notify = MemoryFixer:CreateToggle({
		Name = 'Notify',
		Default = true,
		Tooltip = 'Tells you how many it dropped'
	})
	MemoryFixer:CreateButton({
		Name = 'Clean now',
		Function = function()
			local removed = clean()
			notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
		end
	})
end)

run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local Prediction
	local FOV
	local OtherProjectiles
	local Blacklist
	
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local namecall
	local lastWarn = 0
	
	local function refreshMap()
		local map = workspace:FindFirstChild('Map')
		if map ~= rayCheck.FilterDescendantsInstances[1] then
			rayCheck.FilterDescendantsInstances = map and {map} or {}
		end
	end
	
	local function getMousePosition()
		return gameCamera.ViewportSize / 2
	end
	
	local function getPosition(ent)
		if TargetPart.Value == 'Closest' then
			local localPosition, magnitude, part = getMousePosition(), 9e9, nil
			for _, v in ent:GetChildren() do
				if v:IsA('BasePart') then
					local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)
					if vis then
						local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude
						if mag < magnitude then
							magnitude = mag
							part = v
						end
					end
				end
			end
			return part and part.Position or ent.PrimaryPart and ent.PrimaryPart.Position
		elseif TargetPart.Value == 'Dynamic' then
			local tool = store.hand.tool
			if tool and tool.Name:find('headhunter') and ent:FindFirstChild('Head') then
				return ent.Head.Position
			end
			return ent.PrimaryPart and ent.PrimaryPart.Position
		end
		return
	end
	
	local function solveSilent(args)
		local origin, velocity, projType = args[4], args[6], args[3]
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or type(projType) ~= 'string' then
			return
		end
	
		if (not OtherProjectiles.Enabled) and not projType:find('arrow') then
			return
		end
	
		if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
			return
		end
	
		local meta = bedwars.ProjectileMeta[projType]
		if not meta then return end
	
		local speed = velocity.Magnitude
		if speed <= 0 then return end
		refreshMap()
		local gravity = meta.gravitationalAcceleration or 196.2
	
		local plr = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Priority = Targets.Priority.Value,
			Wallcheck = Targets.Walls.Enabled,
			Sort = sortmethods[Sort.Value or 'Distance'],
			MouseOrigin = getMousePosition(),
			Origin = origin,
		})
		if not plr then return end
	
		local targetpart = getTargetPart(plr, TargetPart.Value)
		local targetpos = getPosition(plr.Character) or targetpart and targetpart.Position
		if not targetpos then return end
		local playerGravity = workspace.Gravity
		local balloons = plr.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end
	
		if plr.Character.PrimaryPart and plr.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
			playerGravity = 6
		end
	
		if plr.Player and plr.Player:GetAttribute('IsOwlTarget') then
			for _, owl in collectionService:GetTagged('Owl') do
				if owl:GetAttribute('Target') == plr.Player.UserId and owl:GetAttribute('Status') == 2 then
					playerGravity = 0
				end
			end
		end
	
		local pearl = projType == 'telepearl'
		local targetVelocity = pearl and Vector3.zero or plr.RootPart.AssemblyLinearVelocity
		local targetAirborne = not pearl and plr.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(targetVelocity.Y) > 0.01
		local calc, _, travelTime = prediction.SolveTrajectory(origin, speed * Prediction.Value, gravity, targetpos, targetVelocity, playerGravity, plr.HipHeight, plr.Jumping and 42.6 or nil, rayCheck, targetAirborne, plr.RootPart.Position, plr.RootPart, nil, true)
		if not calc or not travelTime or travelTime > (meta.lifetimeSec or 3) then return end
	
		targetinfo.Targets[plr] = tick() + 1
		store.hitchance.SilentAim = {Value = getHitChance(plr, travelTime), Clock = tick()}
		return CFrame.lookAt(origin, calc).LookVector * speed
	end
	
	SilentAim = vape.Categories.Combat:CreateModule({
		Name = 'ProjectileTeleport',
		Function = function(callback)
			if callback and not namecall then
				namecall = hookmetamethod(game, '__namecall', newcclosure(function(...)
					if SilentAim.Enabled and not checkcaller() and getnamecallmethod() == 'InvokeServer' and tostring(...) == 'ProjectileFire' then
						local self = ...
						local args = table.pack(select(2, ...))
						local success, newVelocity = pcall(solveSilent, args)
						if success and typeof(newVelocity) == 'Vector3' then
							args[6] = newVelocity
						elseif not success and shared.VapeDeveloper and tick() > lastWarn then
							lastWarn = tick() + 5
							warn('[catvape] silentaim solve failed: '..tostring(newVelocity))
						end
						return namecall(self, table.unpack(args, 1, args.n))
					end
					return namecall(...)
				end))
			end
		end,
		Tooltip = 'Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen'
	})
	Targets = SilentAim:CreateTargets({
		Players = true,
		Walls = true,
	})
	TargetPart = SilentAim:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic', 'Closest'},
	})
	local methods = {'Damage', 'Distance'}
	for _, v in sortlist do
		if not table.find(methods, v) then
			table.insert(methods, v)
		end
	end
	Sort = SilentAim:CreateDropdown({
		Name = 'Target Mode',
		List = methods,
		Default = 'Distance'
	})
	Prediction = SilentAim:CreateSlider({
		Name = 'Prediction',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	OtherProjectiles = SilentAim:CreateToggle({
		Name = 'Other Projectiles',
		Function = function(call)
			if Blacklist and Blacklist.Object then
				Blacklist.Object.Visible = call
			end
		end,
		Default = true
	})
	Blacklist = SilentAim:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile'
	})
end)

run(function()
	local Headless
	local Hats
	
	local hidden = setmetatable({}, {__mode = 'k'})
	
	local function setHidden(character, hide)
		local head = character:FindFirstChild('Head')
		if not head then return end
	
		head.LocalTransparencyModifier = hide and 1 or 0
		for _, v in head:GetChildren() do
			if v:IsA('Decal') then
				if hide and not hidden[v] then
					hidden[v] = v.Transparency
				end
				v.Transparency = hide and 1 or (hidden[v] or 0)
			end
		end
	
		for _, v in character:GetChildren() do
			if v:IsA('Accessory') and v.Handle and v.Handle:FindFirstChild('HatAttachment') then
				v.Handle.LocalTransparencyModifier = hide and Hats.Enabled and 1 or 0
			end
		end
	end
	
	Headless = vape.Categories.Render:CreateModule({
		Name = 'RemoveHead',
		Function = function(callback)
			if callback then
				Headless:Clean(runService.PreRender:Connect(function()
					if entitylib.isAlive then
						setHidden(lplr.Character, true)
					end
				end))
			elseif entitylib.isAlive then
				setHidden(lplr.Character, false)
			end
		end,
		Tooltip = 'Hides your own head'
	})
	Hats = Headless:CreateToggle({
		Name = 'Hide hats',
		Default = true,
		Tooltip = 'Hides anything worn on your head too'
	})
end)

run(function()
	local NameTags
	local Targets
	local Color
	local Background
	local DisplayName
	local Health
	local Distance
	local Equipment
	local Rank
	local Enchant
	local Device
	local DrawingToggle
	local Scale
	local FontOption
	local Teammates
	local DistanceCheck
	local DistanceLimit
	local Strings, Sizes, Reference = {}, {}, {}
	local Folder
	
	pcall(function()
		Folder = Instance.new('Folder')
		Folder.Parent = vape.gui
	end)
	
	local methodused
	-- assigned once the Updated table below exists; lets the rank fetch redraw a tag when
	-- the division finally lands
	local refreshTag

	local RankMeta = (function()
		local suc, res = pcall(function()
			return require(replicatedStorage.TS.rank['rank-meta']).RankMeta
		end)
		return suc and res or nil
	end)()

	local rankRequested = {}

	local function getRankImage(plr)
		if not (RankMeta and plr) then return nil end
		local controller = bedwars.RankController
		local cache = controller and controller.rankCache
		local division = cache and cache[plr.UserId]
		local meta = division and RankMeta[division]
		return meta and meta.image or nil
	end

	local ICON_SIZE = 30
	local rightIcons = {'RankIcon', 'EnchantIcon'}
	local function positionIcons(nametag, width)
		local offset = width + 10
		for _, name in rightIcons do
			local icon = nametag:FindFirstChild(name)
			if icon then
				local shown = icon.Image ~= ''
				icon.Visible = shown
				if shown then
					icon.Position = UDim2.fromOffset(offset, -4)
					offset += ICON_SIZE
				end
			end
		end
	end

	local function requestRank(plr, ent)
		if not plr or rankRequested[plr.UserId] then return end
		local controller = bedwars.RankController
		if not (controller and controller.getRanks) then return end
		rankRequested[plr.UserId] = true
		task.spawn(function()
			pcall(function()
				controller:getRanks({plr.UserId}, true):andThen(function()
					if refreshTag then refreshTag(ent) end
				end)
			end)
		end)
	end

	local function getEnchantImage(plr)
		if not plr then return nil end
		if not (store.enchants and bedwars.EnchantMeta) then return nil end
		local suc, res = pcall(function()
			return store.enchants[plr].async()
		end)
		return suc and res or nil
	end

	local enchantConns = {}

	local function unwatchEnchant(ent)
		local conn = enchantConns[ent]
		if conn then
			pcall(function() conn:Disconnect() end)
			enchantConns[ent] = nil
		end
	end

	local function watchEnchant(ent)
		unwatchEnchant(ent)
		local char = ent.Character
		if not char then return end
		pcall(function()
			enchantConns[ent] = char.AttributeChanged:Connect(function(attribute)
				if attribute:find('StatusEffect_') and refreshTag then
					refreshTag(ent)
				end
			end)
		end)
	end

	local deviceEmojis = {gamepad = '🎮', touch = '📱', keyboard = '🖥️'}

	local function getDeviceEmoji(plr)
		if not plr then return nil end
		local inputType = plr:GetAttribute('UserInputType')
		if inputType == nil and plr.Character then
			inputType = plr.Character:GetAttribute('UserInputType')
		end
		if inputType == nil then return nil end
		if type(inputType) == 'number' then
			if inputType == 7 then return deviceEmojis.touch end
			if inputType == 8 then return deviceEmojis.keyboard end
			if inputType >= 9 and inputType <= 16 then return deviceEmojis.gamepad end
			return deviceEmojis.keyboard
		end
		local name = tostring(inputType):lower()
		if name:find('gamepad') or name:find('console') or name:find('xbox') or name:find('playstation') then
			return deviceEmojis.gamepad
		end
		if name:find('touch') or name:find('mobile') or name:find('phone') or name:find('tablet') then
			return deviceEmojis.touch
		end
		return name ~= '' and deviceEmojis.keyboard or nil
	end

	-- Watch inventory changes for live updates
	local inventoryConns = {}
	local function unwatchInventory(ent)
		local conn = inventoryConns[ent]
		if conn then
			pcall(function() conn:Disconnect() end)
			inventoryConns[ent] = nil
		end
	end

	local function watchInventory(ent)
		unwatchInventory(ent)
		if not ent.Player or not store.inventories then return end
		pcall(function()
			inventoryConns[ent] = ent.Player.CharacterAdded:Connect(function()
				if refreshTag then refreshTag(ent) end
			end)
		end)
	end

	local Added = {
		Normal = function(ent)
			pcall(function()
				if not Targets.Players.Enabled and ent.Player then return end
				if not Targets.NPCs.Enabled and ent.NPC then return end
				if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
				if Reference[ent] then return end

				local nametag = Instance.new('TextLabel')
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end

				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end

				if Equipment.Enabled then
					for i, v in {'Hand', 'Helmet', 'Chestplate', 'Boots', 'Kit'} do
						local Icon = Instance.new('ImageLabel')
						Icon.Name = v
						Icon.Size = UDim2.fromOffset(30, 30)
						Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
						Icon.BackgroundTransparency = 1
						Icon.Image = ''
						Icon.Parent = nametag

						-- Added item amount text overlay for Hand item
						if v == 'Hand' then
							local ValueLabel = Instance.new('TextLabel')
							ValueLabel.Name = 'AmountLabel'
							ValueLabel.Size = UDim2.fromScale(1, 1)
							ValueLabel.Position = UDim2.fromOffset(0, 0)
							ValueLabel.BackgroundTransparency = 1
							ValueLabel.Text = ''
							ValueLabel.TextColor3 = Color3.new(1, 1, 1)
							ValueLabel.TextStrokeTransparency = 0
							ValueLabel.TextSize = 12
							ValueLabel.Font = Enum.Font.SourceSansBold
							ValueLabel.TextXAlignment = Enum.TextXAlignment.Right
							ValueLabel.TextYAlignment = Enum.TextYAlignment.Bottom
							ValueLabel.Parent = Icon
						end
					end
				end

				nametag.TextSize = 14 * Scale.Value
				nametag.FontFace = FontOption.Value
				local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
				nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)

				if Rank.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'RankIcon'
					Icon.Size = UDim2.fromOffset(ICON_SIZE, ICON_SIZE)
					Icon.BackgroundTransparency = 1
					Icon.Image = getRankImage(ent.Player) or ''
					Icon.Visible = false
					Icon.Parent = nametag
					if Icon.Image == '' then
						requestRank(ent.Player, ent)
					end
				end

				if Enchant.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'EnchantIcon'
					Icon.Size = UDim2.fromOffset(ICON_SIZE, ICON_SIZE)
					Icon.BackgroundTransparency = 1
					Icon.Image = getEnchantImage(ent.Player) or ''
					Icon.Visible = false
					Icon.Parent = nametag
					watchEnchant(ent)
				end

				positionIcons(nametag, size.X)

				nametag.AnchorPoint = Vector2.new(0.5, 1)
				nametag.BackgroundColor3 = Color3.new()
				nametag.BackgroundTransparency = Background.Value
				nametag.BorderSizePixel = 0
				nametag.Visible = false
				nametag.Text = Strings[ent]
				nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				nametag.RichText = true
				nametag.Parent = Folder
				Reference[ent] = nametag
				
				if Equipment.Enabled and ent.Player then
					watchInventory(ent)
				end
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				if not Targets.Players.Enabled and ent.Player then return end
				if not Targets.NPCs.Enabled and ent.NPC then return end
				if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
				if Reference[ent] then return end

				local nametag = {}
				nametag.BG = Drawing.new('Square')
				nametag.BG.Filled = true
				nametag.BG.Transparency = 1 - Background.Value
				nametag.BG.Color = Color3.new()
				nametag.BG.ZIndex = 1
				nametag.Text = Drawing.new('Text')
				nametag.Text.Size = 15 * Scale.Value
				nametag.Text.Font = 0
				nametag.Text.ZIndex = 2
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end

				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
				end

				nametag.Text.Text = Strings[ent]
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				Reference[ent] = nametag
			end)
		end
	}
	
	local Removed = {
		Normal = function(ent)
			pcall(function()
				unwatchEnchant(ent)
				unwatchInventory(ent)
				local v = Reference[ent]
				if v then
					Reference[ent] = nil
					Strings[ent] = nil
					Sizes[ent] = nil
					v:Destroy()
				end
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				unwatchEnchant(ent)
				unwatchInventory(ent)
				local v = Reference[ent]
				if v then
					Reference[ent] = nil
					Strings[ent] = nil
					Sizes[ent] = nil
					for _, obj in v do
						pcall(function()
							obj.Visible = false
							obj:Remove()
						end)
					end
				end
			end)
		end
	}
	
	local Updated = {
		Normal = function(ent)
			pcall(function()
				local nametag = Reference[ent]
				if not nametag or not nametag.Parent then return end
				
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end

				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end

				if Equipment.Enabled and store.inventories[ent.Player] and nametag:FindFirstChild("Hand") then
					local kit = ent.Player:GetAttribute('PlayingAsKit')
					local inventory = store.inventories[ent.Player]
					local handItem = inventory.hand or {itemType = '', amount = 1}

					nametag.Hand.Image = bedwars.getIcon(handItem, true)
					nametag.Helmet.Image = bedwars.getIcon(inventory.armor[4] or {itemType = ''}, true)
					nametag.Chestplate.Image = bedwars.getIcon(inventory.armor[5] or {itemType = ''}, true)
					nametag.Boots.Image = bedwars.getIcon(inventory.armor[6] or {itemType = ''}, true)
					nametag.Kit.Image = kit and kit ~= 'none' and bedwars.BedwarsKitMeta[kit].renderImage or ''

					-- Update the item stack count/amount label in real-time
					local amountLabel = nametag.Hand:FindFirstChild('AmountLabel')
					if amountLabel then
						local amount = handItem.amount or handItem.quantity or 1
						if amount > 1 then
							amountLabel.Text = tostring(amount)
						else
							amountLabel.Text = ''
						end
					end
				end

				if Rank.Enabled and ent.Player then
					local icon = nametag:FindFirstChild('RankIcon')
					if icon then
						icon.Image = getRankImage(ent.Player) or ''
					end
				end

				if Enchant.Enabled and ent.Player then
					local icon = nametag:FindFirstChild('EnchantIcon')
					if icon then
						icon.Image = getEnchantImage(ent.Player) or ''
					end
				end

				local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
				positionIcons(nametag, size.X)
				nametag.Text = Strings[ent]
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				local nametag = Reference[ent]
				if not nametag then return end
				
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end

				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
					nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
				else
					nametag.Text.Text = Strings[ent]
				end

				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			end)
		end
	}
	
	refreshTag = function(ent)
		if Reference[ent] and Updated[methodused] then
			Updated[methodused](ent)
		end
	end

	local ColorFunc = {
		Normal = function(hue, sat, val)
			pcall(function()
				local color = Color3.fromHSV(hue, sat, val)
				for i, v in Reference do
					if v and v.Parent then
						v.TextColor3 = entitylib.getEntityColor(i) or color
					end
				end
			end)
		end,
		Drawing = function(hue, sat, val)
			pcall(function()
				local color = Color3.fromHSV(hue, sat, val)
				for i, v in Reference do
					if v and v.Text then
						v.Text.Color = entitylib.getEntityColor(i) or color
					end
				end
			end)
		end
	}
	
	local Loop = {
		Normal = function()
			pcall(function()
				local selfPos = entitylib.isAlive and entitylib.character.RootPart.Position
				for ent, nametag in Reference do
					if not nametag or not nametag.Parent then
						Reference[ent] = nil
						continue
					end
					
					if DistanceCheck.Enabled then
						local distance = selfPos and (selfPos - ent.RootPart.Position).Magnitude or math.huge
						if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
							nametag.Visible = false
							continue
						end
					end

					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
					nametag.Visible = headVis
					if not headVis then
						continue
					end

					if Distance.Enabled then
						local mag = selfPos and math.floor((selfPos - ent.RootPart.Position).Magnitude) or 0
						if Sizes[ent] ~= mag then
							nametag.Text = string.format(Strings[ent], mag)
							local ize = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
							nametag.Size = UDim2.fromOffset(ize.X + 8, ize.Y + 7)
							positionIcons(nametag, ize.X)
							Sizes[ent] = mag
						end
					end
					
					-- Live update equipment amounts
					if Equipment.Enabled and store.inventories[ent.Player] then
						local inventory = store.inventories[ent.Player]
						local handItem = inventory.hand or {itemType = '', amount = 1}
						local amountLabel = nametag:FindFirstChild('Hand') and nametag.Hand:FindFirstChild('AmountLabel')
						
						if amountLabel then
							local amount = handItem.amount or handItem.quantity or 1
							local newText = amount > 1 and tostring(amount) or ''
							if amountLabel.Text ~= newText then
								amountLabel.Text = newText
							end
						end
					end
					
					nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
				end
			end)
		end,
		Drawing = function()
			pcall(function()
				local selfPos = entitylib.isAlive and entitylib.character.RootPart.Position
				for ent, nametag in Reference do
					if not nametag or not nametag.Text or not nametag.BG then
						Reference[ent] = nil
						continue
					end

					if DistanceCheck.Enabled then
						local distance = selfPos and (selfPos - ent.RootPart.Position).Magnitude or math.huge
						if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
							nametag.Text.Visible = false
							nametag.BG.Visible = false
							continue
						end
					end

					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
					nametag.Text.Visible = headVis
					nametag.BG.Visible = headVis
					if not headVis then
						continue
					end

					if Distance.Enabled then
						local mag = selfPos and math.floor((selfPos - ent.RootPart.Position).Magnitude) or 0
						if Sizes[ent] ~= mag then
							nametag.Text.Text = string.format(Strings[ent], mag)
							nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
							Sizes[ent] = mag
						end
					end
					nametag.BG.Position = Vector2.new(headPos.X - (nametag.BG.Size.X / 2), headPos.Y - nametag.BG.Size.Y)
					nametag.Text.Position = nametag.BG.Position + Vector2.new(4, 3)
				end
			end)
		end
	}
	
	NameTags = vape.Categories.Render:CreateModule({
		Name = 'NameTags',
		Function = function(callback)
			if callback then
				methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
				if Removed[methodused] then
					NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
				end
				if Added[methodused] then
					for _, v in entitylib.List do
						if Reference[v] then
							Removed[methodused](v)
						end
						Added[methodused](v)
					end
					NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
						if Reference[ent] then
							Removed[methodused](ent)
						end
						Added[methodused](ent)
					end))
				end
				if Updated[methodused] then
					NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
					for _, v in entitylib.List do
						Updated[methodused](v)
					end
				end
				if ColorFunc[methodused] then
					NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
						ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
					end))
				end
				if Loop[methodused] then
					NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
				end

				local function watchDevice(plr)
					NameTags:Clean(plr:GetAttributeChangedSignal('UserInputType'):Connect(function()
						if not Device.Enabled then return end
						local ent = entitylib.getEntity(plr)
						if ent then
							refreshTag(ent)
						end
					end))
				end

				for _, plr in playersService:GetPlayers() do
					watchDevice(plr)
				end
				NameTags:Clean(playersService.PlayerAdded:Connect(watchDevice))
			else
				if Removed[methodused] then
					for i in Reference do
						Removed[methodused](i)
					end
				end
				for ent in enchantConns do
					unwatchEnchant(ent)
				end
				for ent in inventoryConns do
					unwatchInventory(ent)
				end
			end
		end,
		Tooltip = 'Renders nametags on entities through walls.'
	})
	Targets = NameTags:CreateTargets({
		Players = true,
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	FontOption = NameTags:CreateFont({
		Name = 'Font',
		Blacklist = 'Arial',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Color = NameTags:CreateColorSlider({
		Name = 'Player Color',
		Function = function(hue, sat, val)
			if NameTags.Enabled and ColorFunc[methodused] then
				ColorFunc[methodused](hue, sat, val)
			end
		end
	})
	Scale = NameTags:CreateSlider({
		Name = 'Scale',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 1,
		Min = 0.1,
		Max = 1.5,
		Decimal = 10
	})
	Background = NameTags:CreateSlider({
		Name = 'Transparency',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 0.5,
		Min = 0,
		Max = 1,
		Decimal = 10
	})
	Health = NameTags:CreateToggle({
		Name = 'Health',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Distance = NameTags:CreateToggle({
		Name = 'Distance',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Equipment = NameTags:CreateToggle({
		Name = 'Equipment',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Rank = NameTags:CreateToggle({
		Name = 'Show Rank',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows the ranked division icon above the nametag'
	})
	Enchant = NameTags:CreateToggle({
		Name = 'Show Enchant',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows the player\'s active enchant icon above the nametag (Drawing mode has no icons)'
	})
	Device = NameTags:CreateToggle({
		Name = 'Show Device',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows 🎮 / 🖥️ / 📱 for the input device the player is on'
	})
	DisplayName = NameTags:CreateToggle({
		Name = 'Use Displayname',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	Teammates = NameTags:CreateToggle({
		Name = 'Priority Only',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	DrawingToggle = NameTags:CreateToggle({
		Name = 'Drawing',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
	})
	DistanceCheck = NameTags:CreateToggle({
		Name = 'Distance Check',
		Function = function(callback)
			DistanceLimit.Object.Visible = callback
		end
	})
	DistanceLimit = NameTags:CreateTwoSlider({
		Name = 'Player Distance',
		Min = 0,
		Max = 256,
		DefaultMin = 0,
		DefaultMax = 64,
		Darker = true,
		Visible = false
	})
end)

run(function()
	local GeneratorESP
	DiamondToggle = nil
	EmeraldToggle = nil
	TeamGenToggle = nil
	ShowOwnTeamGen = nil
	ShowEnemyTeamGen = nil
	local UIStyle
	local CompactDiamondToggle
	local CompactEmeraldToggle
	local CollectionService = collectionService
	local RunService = runService
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local CompactFolder = Instance.new('Folder')
	CompactFolder.Parent = vape.gui
	local teamColors = getgenv().aeroTeamColors

	local generatorTypes = {
		diamond = {
			keywords = {'diamond'},
			color = Color3.fromRGB(85, 200, 255),
			icon = 'diamond',
			displayName = 'Diamond',
			isTeamGen = false
		},
		emerald = {
			keywords = {'emerald'},
			color = Color3.fromRGB(0, 255, 100),
			icon = 'emerald',
			displayName = 'Emerald',
			isTeamGen = false
		}
	}

	local compactUI = Instance.new('ScreenGui')
	compactUI.Name = 'GeneratorCompactUI'
	compactUI.Parent = vape.gui
	compactUI.Enabled = false
	compactUI.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	compactUI.DisplayOrder = 10
	compactUI.ResetOnSpawn = false

	local mainFrame = Instance.new('Frame')
	mainFrame.Name = 'MainFrame'
	mainFrame.Parent = compactUI
	mainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
	mainFrame.BackgroundTransparency = 0.3
	mainFrame.BorderSizePixel = 0
	mainFrame.Position = UDim2.new(1, -8, 1, -8)
	mainFrame.Size = UDim2.new(0, 120, 0, 100)
	mainFrame.AnchorPoint = Vector2.new(1, 1)

	local uicorner = Instance.new('UICorner')
	uicorner.CornerRadius = UDim.new(0, 8)
	uicorner.Parent = mainFrame

	local title = Instance.new('TextLabel')
	title.Name = 'Title'
	title.Parent = mainFrame
	title.BackgroundTransparency = 1
	title.Size = UDim2.new(1, 0, 0, 25)
	title.Position = UDim2.new(0, 0, 0, 5)
	title.Text = "GEN ESP"
	title.TextColor3 = Color3.fromRGB(255, 255, 255)
	title.TextSize = 14
	title.Font = Enum.Font.GothamBold
	title.TextStrokeTransparency = 0.5
	title.TextStrokeColor3 = Color3.new(0, 0, 0)

	local diamondFrame = Instance.new('Frame')
	diamondFrame.Name = 'DiamondFrame'
	diamondFrame.Parent = mainFrame
	diamondFrame.BackgroundTransparency = 1
	diamondFrame.Size = UDim2.new(1, -20, 0, 25)
	diamondFrame.Position = UDim2.new(0, 10, 0, 35)

	local diamondIcon = Instance.new('ImageLabel')
	diamondIcon.Name = 'DiamondIcon'
	diamondIcon.Parent = diamondFrame
	diamondIcon.BackgroundTransparency = 1
	diamondIcon.Size = UDim2.new(0, 18, 0, 18)
	diamondIcon.Position = UDim2.new(0, 0, 0.5, -9)
	diamondIcon.Image = bedwars.getIcon({itemType = 'diamond'}, true)

	local diamondTimer = Instance.new('TextLabel')
	diamondTimer.Name = 'DiamondTimer'
	diamondTimer.Parent = diamondFrame
	diamondTimer.BackgroundTransparency = 1
	diamondTimer.Size = UDim2.new(1, -25, 1, 0)
	diamondTimer.Position = UDim2.new(0, 25, 0, 0)
	diamondTimer.Text = "00"
	diamondTimer.TextColor3 = Color3.fromRGB(85, 200, 255)
	diamondTimer.TextSize = 18
	diamondTimer.Font = Enum.Font.GothamBold
	diamondTimer.TextXAlignment = Enum.TextXAlignment.Left

	local emeraldFrame = Instance.new('Frame')
	emeraldFrame.Name = 'EmeraldFrame'
	emeraldFrame.Parent = mainFrame
	emeraldFrame.BackgroundTransparency = 1
	emeraldFrame.Size = UDim2.new(1, -20, 0, 25)
	emeraldFrame.Position = UDim2.new(0, 10, 0, 65)

	local emeraldIcon = Instance.new('ImageLabel')
	emeraldIcon.Name = 'EmeraldIcon'
	emeraldIcon.Parent = emeraldFrame
	emeraldIcon.BackgroundTransparency = 1
	emeraldIcon.Size = UDim2.new(0, 18, 0, 18)
	emeraldIcon.Position = UDim2.new(0, 0, 0.5, -9)
	emeraldIcon.Image = bedwars.getIcon({itemType = 'emerald'}, true)

	local emeraldTimer = Instance.new('TextLabel')
	emeraldTimer.Name = 'EmeraldTimer'
	emeraldTimer.Parent = emeraldFrame
	emeraldTimer.BackgroundTransparency = 1
	emeraldTimer.Size = UDim2.new(1, -25, 1, 0)
	emeraldTimer.Position = UDim2.new(0, 25, 0, 0)
	emeraldTimer.Text = "00"
	emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
	emeraldTimer.TextSize = 18
	emeraldTimer.Font = Enum.Font.GothamBold
	emeraldTimer.TextXAlignment = Enum.TextXAlignment.Left

	local diamondTimes = {}
	local emeraldTimes = {}

	local function getMyTeamId()
		local myTeam = lplr:GetAttribute('Team')
		if myTeam == nil then return nil end
		return tonumber(myTeam)
	end

	local function getGeneratorTeamId(generatorId)
		local teamNum = string.match(generatorId, "^(%d+)_generator")
		if teamNum then
			return tonumber(teamNum)
		end
		return nil
	end

	local function isTeamGenerator(generatorId)
		return string.match(generatorId, "^%d+_generator") ~= nil
	end

	local function getGeneratorType(generatorId)
		local idLower = string.lower(generatorId)

		if isTeamGenerator(generatorId) then
			return 'teamgen', {
				color = Color3.fromRGB(200, 200, 200),
				icon = 'iron',
				displayName = 'Team Gen',
				isTeamGen = true
			}
		end

		for genType, config in pairs(generatorTypes) do
			for _, keyword in ipairs(config.keywords) do
				if idLower:find(keyword) then
					return genType, config
				end
			end
		end
		return nil, nil
	end

	local function isGeneratorEnabled(genType, teamId)
		if genType == 'diamond' then
			return DiamondToggle.Enabled
		elseif genType == 'emerald' then
			return EmeraldToggle.Enabled
		elseif genType == 'teamgen' then
			if not TeamGenToggle.Enabled then return false end
			local myTeamId = getMyTeamId()
			if not myTeamId or not teamId then return TeamGenToggle.Enabled end
			if teamId == myTeamId then
				return ShowOwnTeamGen.Enabled
			else
				return ShowEnemyTeamGen.Enabled
			end
		end
		return false
	end

	local function getProperIcon(iconType)
		local icon = bedwars.getIcon({itemType = iconType}, true)
		if not icon or icon == "" then return nil end
		return icon
	end

	local function getTierText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if globalGen then
			for _, child in pairs(globalGen:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		local teamGenMain = teamApp:FindFirstChild('TeamGenMain')
		if teamGenMain then
			for _, child in pairs(teamGenMain:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		return nil
	end

	local function extractTierLevel(tierText)
		if not tierText or tierText == "" then return "0" end
		if tierText == "0" then return "0" end
		local tierMatch = tierText:match("Tier%s+([IVX]+)")
		if tierMatch then return tierMatch end
		if tierText:match("^[IVX]+$") then return tierText end
		local numTier = tierText:match("Tier%s+(%d+)")
		if numTier then
			local num = tonumber(numTier)
			if num == 0 then return "0"
			elseif num == 1 then return "I"
			elseif num == 2 then return "II"
			elseif num == 3 then return "III"
			end
		end
		return "0"
	end

	local function getCountdownText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if not globalGen then return nil end
		local countdown = globalGen:FindFirstChild('Countdown')
		if not countdown then return nil end
		local textLabel = countdown:FindFirstChild('Text')
		if not textLabel then
			if countdown:IsA('TextLabel') then return countdown end
			return nil
		end
		return textLabel
	end

	local function extractSecondsFromText(text)
		if not text or text == "" then return 0 end
		local seconds = text:match("%[(%d+)%]")
		if seconds then return tonumber(seconds) or 0 end
		local justNumber = text:match("(%d+)")
		if justNumber then return tonumber(justNumber) or 0 end
		return 0
	end

	local function getResourceCount(position, resourceType)
		local count = 0
		for _, drop in pairs(CollectionService:GetTagged('ItemDrop')) do
			if drop:FindFirstChild('Handle') then
				local dropName = drop.Name:lower()
				if dropName:find(resourceType) then
					local dist = (drop.Handle.Position - position).Magnitude
					if dist <= 10 then
						local amount = drop:GetAttribute('Amount') or 1
						count = count + amount
					end
				end
			end
		end
		return count
	end

	local CompactGenerators = {}

	local function rebuildCompactGenerators()
		table.clear(CompactGenerators)
		scanDescendants(workspace, function(obj)
			if obj.Name == 'GeneratorAdornee' then
				local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
				if ok and generatorId and type(generatorId) == 'string' and generatorId ~= '' then
					local genType = getGeneratorType(generatorId)
					if genType == 'diamond' or genType == 'emerald' then
						table.insert(CompactGenerators, {obj = obj, genType = genType})
					end
				end
			end
		end)
	end

	local function updateCompactUI()
		if not GeneratorESP.Enabled or UIStyle.Value ~= 'Compact' then
			compactUI.Enabled = false
			return
		end
		compactUI.Enabled = true
		local bestDiamondTime = math.huge
		local bestEmeraldTime = math.huge
		for i = #CompactGenerators, 1, -1 do
			local entry = CompactGenerators[i]
			if not entry.obj or not entry.obj.Parent then
				table.remove(CompactGenerators, i)
				continue
			end
			local countdownText = getCountdownText(entry.obj)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if entry.genType == 'diamond' and timeLeft > 0 and timeLeft < bestDiamondTime then
					bestDiamondTime = timeLeft
				elseif entry.genType == 'emerald' and timeLeft > 0 and timeLeft < bestEmeraldTime then
					bestEmeraldTime = timeLeft
				end
			end
		end
		local showDiamond = CompactDiamondToggle and CompactDiamondToggle.Enabled
		local showEmerald = CompactEmeraldToggle and CompactEmeraldToggle.Enabled

		if not showDiamond and not showEmerald then
			compactUI.Enabled = false
			return
		end

		diamondFrame.Visible = showDiamond
		emeraldFrame.Visible = showEmerald

		if showDiamond then
			diamondFrame.Position = UDim2.new(0, 10, 0, 35)
		end
		if showEmerald then
			emeraldFrame.Position = UDim2.new(0, 10, 0, showDiamond and 65 or 35)
		end

		diamondTimes[1] = bestDiamondTime ~= math.huge and bestDiamondTime or 0
		emeraldTimes[1] = bestEmeraldTime ~= math.huge and bestEmeraldTime or 0
		if bestDiamondTime == math.huge then
			diamondTimer.Text = "00"
		else
			diamondTimer.Text = string.format("%02d", bestDiamondTime)
			if bestDiamondTime <= 5 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestDiamondTime <= 10 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				diamondTimer.TextColor3 = Color3.fromRGB(85, 200, 255)
			end
		end
		if bestEmeraldTime == math.huge then
			emeraldTimer.Text = "00"
		else
			emeraldTimer.Text = string.format("%02d", bestEmeraldTime)
			if bestEmeraldTime <= 5 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestEmeraldTime <= 10 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
			end
		end
	end

	local function clearAllESP()
		Folder:ClearAllChildren()
		table.clear(Reference)
		compactUI.Enabled = false
	end

	local function createESP(generatorAdornee, genType, config, position, teamId)
		if not isGeneratorEnabled(genType, teamId) then return end
		if Reference[generatorAdornee] then return end

		if UIStyle.Value == 'Compact' then
			Reference[generatorAdornee] = {
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = config.isTeamGen
			}
			return
		end
		if not generatorAdornee or not generatorAdornee.Parent then return end

		local displayColor = config.color
		local teamName = nil
		if config.isTeamGen and teamId and teamColors[teamId] then
			displayColor = teamColors[teamId].color
			teamName = teamColors[teamId].name
		end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'generator-esp-' .. genType
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = generatorAdornee
		billboard.Enabled = true  

		if config.isTeamGen then
			billboard.Size = UDim2.fromOffset(180, 55)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)
		else
			billboard.Size = UDim2.fromOffset(80, 30)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
		end

		local blur = pcall(function()
			return addBlur(billboard)
		end) and blur or nil
		if blur then
			blur.Visible = true
		end

		if config.isTeamGen and teamName then
			local dot = Instance.new('Frame')
			dot.Name = 'TeamDot'
			dot.Parent = billboard
			dot.Size = UDim2.fromOffset(8, 8)
			dot.Position = UDim2.new(0, 10, 0, 5)
			dot.BackgroundColor3 = displayColor
			dot.BorderSizePixel = 0
			local dotCorner = Instance.new('UICorner')
			dotCorner.CornerRadius = UDim.new(1, 0)
			dotCorner.Parent = dot

			local teamLabel = Instance.new('TextLabel')
			teamLabel.Name = 'TeamLabel'
			teamLabel.Parent = billboard
			teamLabel.BackgroundTransparency = 1
			teamLabel.Size = UDim2.new(1, 0, 0, 18)
			teamLabel.Position = UDim2.new(0, 0, 0, 0)
			teamLabel.Text = teamName
			teamLabel.TextColor3 = displayColor
			teamLabel.TextSize = 13
			teamLabel.Font = Enum.Font.GothamBold
			teamLabel.TextStrokeTransparency = 0.4
			teamLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			teamLabel.TextXAlignment = Enum.TextXAlignment.Center
		end

		local frame = Instance.new('Frame')
		frame.Size = config.isTeamGen and UDim2.new(1, 0, 0, 35) or UDim2.fromScale(1, 1)
		frame.Position = config.isTeamGen and UDim2.new(0, 0, 0, 20) or UDim2.new(0, 0, 0, 0)
		frame.BackgroundColor3 = Color3.new(0, 0, 0)
		frame.BackgroundTransparency = 0.3
		frame.BorderSizePixel = 0
		frame.Parent = billboard

		if config.isTeamGen and teamId and teamColors[teamId] then
			local stripe = Instance.new('Frame')
			stripe.Name = 'TeamStripe'
			stripe.Parent = frame
			stripe.Size = UDim2.new(0, 3, 1, 0)
			stripe.Position = UDim2.new(0, 0, 0, 0)
			stripe.BackgroundColor3 = displayColor
			stripe.BorderSizePixel = 0
			local stripeCorner = Instance.new('UICorner')
			stripeCorner.CornerRadius = UDim.new(0, 3)
			stripeCorner.Parent = stripe
		end

		local uicorner2 = Instance.new('UICorner')
		uicorner2.CornerRadius = UDim.new(0, 6)
		uicorner2.Parent = frame

		if config.isTeamGen then
			local tierLabel = Instance.new('TextLabel')
			tierLabel.Name = 'Tier'
			tierLabel.Size = UDim2.new(0, 25, 1, 0)
			tierLabel.Position = UDim2.new(0, 8, 0, 0)
			tierLabel.BackgroundTransparency = 1
			tierLabel.Text = "0"
			tierLabel.TextColor3 = Color3.fromRGB(255, 255, 100)
			tierLabel.TextSize = 16
			tierLabel.Font = Enum.Font.GothamBold
			tierLabel.TextStrokeTransparency = 0.5
			tierLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			tierLabel.Parent = frame

			local resources = {
				{name = 'iron',    color = Color3.fromRGB(200, 200, 200), icon = 'iron',    xOffset = 35},
				{name = 'diamond', color = Color3.fromRGB(85, 200, 255),  icon = 'diamond', xOffset = 85},
				{name = 'emerald', color = Color3.fromRGB(0, 255, 100),   icon = 'emerald', xOffset = 135}
			}

			local resourceLabels = {}
			for _, resource in ipairs(resources) do
				local iconImage = getProperIcon(resource.icon)
				if iconImage then
					local image = Instance.new('ImageLabel')
					image.Size = UDim2.fromOffset(18, 18)
					image.Position = UDim2.new(0, resource.xOffset, 0.5, 0)
					image.AnchorPoint = Vector2.new(0, 0.5)
					image.BackgroundTransparency = 1
					image.Image = iconImage
					image.Parent = frame
				end
				local countLabel = Instance.new('TextLabel')
				countLabel.Name = resource.name .. '_count'
				countLabel.Size = UDim2.new(0, 25, 1, 0)
				countLabel.Position = UDim2.new(0, resource.xOffset + 20, 0, 0)
				countLabel.BackgroundTransparency = 1
				countLabel.Text = "0"
				countLabel.TextColor3 = resource.color
				countLabel.TextSize = 16
				countLabel.Font = Enum.Font.GothamBold
				countLabel.TextStrokeTransparency = 0.5
				countLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
				countLabel.TextXAlignment = Enum.TextXAlignment.Left
				countLabel.Parent = frame
				resourceLabels[resource.name] = countLabel
			end

			Reference[generatorAdornee] = {
				billboard = billboard,
				tierLabel = tierLabel,
				ironLabel = resourceLabels.iron,
				diamondLabel = resourceLabels.diamond,
				emeraldLabel = resourceLabels.emerald,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = true
			}
		else
			local iconImage = getProperIcon(config.icon)
			if iconImage then
				local image = Instance.new('ImageLabel')
				image.Size = UDim2.fromOffset(20, 20)
				image.Position = UDim2.new(0, 5, 0.5, 0)
				image.AnchorPoint = Vector2.new(0, 0.5)
				image.BackgroundTransparency = 1
				image.Image = iconImage
				image.Parent = frame
			end
			local timerLabel = Instance.new('TextLabel')
			timerLabel.Name = 'Timer'
			timerLabel.Size = UDim2.new(0, 30, 1, 0)
			timerLabel.Position = UDim2.new(0.5, 0, 0, 0)
			timerLabel.AnchorPoint = Vector2.new(0.5, 0)
			timerLabel.BackgroundTransparency = 1
			timerLabel.Text = "00"
			timerLabel.TextColor3 = displayColor
			timerLabel.TextSize = 18
			timerLabel.Font = Enum.Font.GothamBold
			timerLabel.TextStrokeTransparency = 0.5
			timerLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			timerLabel.Parent = frame
			local amountLabel = Instance.new('TextLabel')
			amountLabel.Name = 'Amount'
			amountLabel.Size = UDim2.new(0, 20, 1, 0)
			amountLabel.Position = UDim2.new(1, -20, 0, 0)
			amountLabel.BackgroundTransparency = 1
			amountLabel.Text = "0"
			amountLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			amountLabel.TextSize = 16
			amountLabel.Font = Enum.Font.GothamBold
			amountLabel.TextStrokeTransparency = 0.5
			amountLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			amountLabel.Parent = frame
			Reference[generatorAdornee] = {
				billboard = billboard,
				timerLabel = timerLabel,
				amountLabel = amountLabel,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = false
			}
		end
		billboard.Enabled = true
	end

	local function updateESP(generatorAdornee)
		local ref = Reference[generatorAdornee]
		if not ref then return end
		if UIStyle.Value == 'Compact' then return end

		if ref.isTeamGen then
			if ref.tierLabel then
				local tierTextLabel = getTierText(generatorAdornee)
				if tierTextLabel and tierTextLabel.Text then
					ref.tierLabel.Text = extractTierLevel(tierTextLabel.Text)
				else
					ref.tierLabel.Text = "0"
				end
			end
			if ref.ironLabel then
				ref.ironLabel.Text = tostring(getResourceCount(ref.position, 'iron'))
			end
			if ref.diamondLabel then
				ref.diamondLabel.Text = tostring(getResourceCount(ref.position, 'diamond'))
			end
			if ref.emeraldLabel then
				ref.emeraldLabel.Text = tostring(getResourceCount(ref.position, 'emerald'))
			end
		else
			local countdownText = getCountdownText(generatorAdornee)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if ref.timerLabel then
					ref.timerLabel.Text = string.format("%02d", timeLeft)
					if timeLeft <= 5 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 50, 50)
					elseif timeLeft <= 10 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 165, 0)
					else
						ref.timerLabel.TextColor3 = generatorTypes[ref.genType].color
					end
				end
			else
				if ref.timerLabel then
					ref.timerLabel.Text = "00"
					ref.timerLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
				end
			end
			if ref.amountLabel then
				ref.amountLabel.Text = tostring(getResourceCount(ref.position, ref.genType))
			end
		end
	end

	local function processGeneratorAdornee(obj)
		if obj.Name ~= 'GeneratorAdornee' then return end
		local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
		if not ok then return end
		if generatorId == nil then return end
		if type(generatorId) ~= 'string' then return end
		if generatorId == '' then return end

		local position = obj:GetPivot().Position
		local genType, config = getGeneratorType(generatorId)
		if not genType or not config then return end

		local teamId = getGeneratorTeamId(generatorId)
		if isGeneratorEnabled(genType, teamId) then
			createESP(obj, genType, config, position, teamId)
		end
	end

	local function findAllGenerators()
		scanDescendants(workspace, function(obj)
			pcall(processGeneratorAdornee, obj)
		end)
	end

	local function refreshESP()
		clearAllESP()
		if GeneratorESP.Enabled then
			findAllGenerators()
		end
	end

	local updateTimer = 0

	GeneratorESP = vape.Categories.Render:CreateModule({
		Name = 'GeneratorESP',
		Function = function(callback)
			if callback then
				findAllGenerators()
				rebuildCompactGenerators()

				GeneratorESP:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					task.wait(0.2)
					pcall(processGeneratorAdornee, obj)
					if obj.Name == 'GeneratorAdornee' then
						rebuildCompactGenerators()
					end
				end))

				GeneratorESP:Clean(runService.Heartbeat:Connect(function(dt)
					if not GeneratorESP.Enabled then return end
					updateTimer = updateTimer + dt
					if updateTimer < 0.2 then return end
					updateTimer = 0
					for generatorAdornee, ref in pairs(Reference) do
						if generatorAdornee and generatorAdornee.Parent then
							updateESP(generatorAdornee)
						else
							if ref.billboard then ref.billboard:Destroy() end
							Reference[generatorAdornee] = nil
						end
					end
					updateCompactUI()
				end))

				GeneratorESP:Clean(workspace.DescendantRemoving:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					if Reference[obj] then
						if Reference[obj].billboard then Reference[obj].billboard:Destroy() end
						Reference[obj] = nil
					end
				end))
			else
				clearAllESP()
			end
		end,
		Tooltip = 'esp for generators showing timer and items count'
	})

	UIStyle = GeneratorESP:CreateDropdown({
		Name = 'UI Style',
		List = {'Original', 'Compact'},
		Default = 'Original',
		Function = function(val)
			local isOriginal = val == 'Original'
			if DiamondToggle then DiamondToggle.Object.Visible = isOriginal end
			if EmeraldToggle then EmeraldToggle.Object.Visible = isOriginal end
			if TeamGenToggle then TeamGenToggle.Object.Visible = isOriginal end
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if CompactDiamondToggle then CompactDiamondToggle.Object.Visible = not isOriginal end
			if CompactEmeraldToggle then CompactEmeraldToggle.Object.Visible = not isOriginal end
			refreshESP()
		end,
		Tooltip = 'pick between the norm billboard esp on generators or a ui with timers for generators '
	})

	DiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Diamond',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	EmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Emerald',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	CompactDiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Diamond',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	CompactEmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Emerald',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	TeamGenToggle = GeneratorESP:CreateToggle({
		Name = 'Team Generators',
		Function = function(callback)
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = callback end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = callback end
			refreshESP()
		end,
		Default = true
	})

	ShowOwnTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Own Team',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	ShowEnemyTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Enemy Teams',
		Function = function() refreshESP() end,
		Default = true,
		Visible = true
	})
end)

run(function()
    local InventoryESP
    local Empty
    local Color = {}
    local windows = {} -- Track all player windows
    local playerWindows = {} -- Map player to their window
    local headshots, nametags = {}, {}
    local invLabels, invGrids, personalLabels, personalGrids = {}, {}, {}, {}
    local armordividers, armorholders = {}, {}
    local slots, personalslots, armorslots = {}, {}, {}
    
    local SlotCount = 24
    local PersonalSlotCount = 24
    local SlotSize = 28
    local SlotPadding = 2
    local Columns = 6
    local HeaderHeight = 40
    local WindowWidth = 200
    local WindowSpacing = 5

    local function createSlot(parent)
        local slot = Instance.new('Frame')
        slot.Size = UDim2.fromOffset(SlotSize, SlotSize)
        slot.BackgroundColor3 = color.Dark(uipallet.Main, 0.02)
        slot.BorderSizePixel = 0
        slot.Visible = false
        slot.Parent = parent
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = slot
        
        local stroke = Instance.new('UIStroke')
        stroke.Color = color.Light(uipallet.Main, 0.034)
        stroke.Parent = slot
        
        local icon = Instance.new('ImageLabel')
        icon.Name = 'Icon'
        icon.Size = UDim2.fromOffset(SlotSize - 8, SlotSize - 8)
        icon.Position = UDim2.fromScale(0.5, 0.5)
        icon.AnchorPoint = Vector2.new(0.5, 0.5)
        icon.BackgroundTransparency = 1
        icon.Parent = slot
        
        local amount = Instance.new('TextLabel')
        amount.Name = 'Amount'
        amount.Size = UDim2.fromOffset(SlotSize - 4, 9)
        amount.Position = UDim2.fromOffset(0, SlotSize - 11)
        amount.BackgroundTransparency = 1
        amount.Text = ''
        amount.TextXAlignment = Enum.TextXAlignment.Right
        amount.TextSize = 9
        amount.TextColor3 = uipallet.Text
        amount.TextStrokeColor3 = Color3.new()
        amount.TextStrokeTransparency = 0.4
        amount.FontFace = uipallet.Font
        amount.Parent = slot
        return slot
    end

    local function createSectionHeader(text, parent)
        local label = Instance.new('TextLabel')
        label.Name = text .. 'Header'
        label.Size = UDim2.new(1, -20, 0, 12)
        label.BackgroundTransparency = 1
        label.Text = text
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextSize = 9
        label.TextColor3 = uipallet.Text
        label.FontFace = uipallet.Font
        label.Visible = false
        label.Parent = parent
        return label
    end

    local function buildWindow(player)
        local window = Instance.new('Frame')
        window.Name = 'ViewInventory_' .. player.Name
        window.Size = UDim2.fromOffset(WindowWidth, HeaderHeight)
        window.BackgroundColor3 = uipallet.Main
        window.BackgroundTransparency = 1 - (Color.Opacity or 0.5)
        window.Visible = false
        window.Parent = vape.gui.ScaledGui
        addBlur(window)
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = window
        
        -- Priority outline (light grey stroke for target/closest)
        local priorityStroke = Instance.new('UIStroke')
        priorityStroke.Name = 'PriorityStroke'
        priorityStroke.Color = Color3.fromRGB(200, 200, 200)
        priorityStroke.Thickness = 3
        priorityStroke.Transparency = 1 -- Hidden by default
        priorityStroke.Parent = window

        local headshot = Instance.new('ImageLabel')
        headshot.Name = 'Headshot'
        headshot.Size = UDim2.fromOffset(22, 22)
        headshot.Position = UDim2.fromOffset(10, 9)
        headshot.BackgroundColor3 = color.Dark(uipallet.Main, 0.02)
        headshot.Image = ''
        headshot.Parent = window
        local headcorner = Instance.new('UICorner')
        headcorner.CornerRadius = UDim.new(0, 4)
        headcorner.Parent = headshot

        local kitLogo = Instance.new('ImageLabel')
        kitLogo.Name = 'KitLogo'
        kitLogo.Size = UDim2.fromOffset(16, 16)
        kitLogo.Position = UDim2.fromOffset(42, 12)
        kitLogo.BackgroundTransparency = 1
        kitLogo.Image = ''
        kitLogo.Parent = window

        local nametag = Instance.new('TextLabel')
        nametag.Name = 'Name'
        nametag.Size = UDim2.new(1, -70, 0, 20)
        nametag.Position = UDim2.fromOffset(62, 10)
        nametag.BackgroundTransparency = 1
        nametag.Text = ''
        nametag.TextXAlignment = Enum.TextXAlignment.Left
        nametag.TextSize = 11
        nametag.TextColor3 = uipallet.Text
        nametag.TextTruncate = Enum.TextTruncate.AtEnd
        nametag.FontFace = uipallet.Font
        nametag.Parent = window

        local divider = Instance.new('Frame')
        divider.Name = 'Divider'
        divider.Size = UDim2.new(1, 0, 0, 1)
        divider.Position = UDim2.fromOffset(0, HeaderHeight - 1)
        divider.BackgroundColor3 = color.Light(uipallet.Main, 0.04)
        divider.BorderSizePixel = 0
        divider.Parent = window

        local invLabel = createSectionHeader('Inventory', window)
        local invGrid = Instance.new('Frame')
        invGrid.Name = 'InventoryItems'
        invGrid.Size = UDim2.new(1, -28, 0, 0)
        invGrid.BackgroundTransparency = 1
        invGrid.Parent = window
        local layout1 = Instance.new('UIGridLayout')
        layout1.CellSize = UDim2.fromOffset(SlotSize, SlotSize)
        layout1.CellPadding = UDim2.fromOffset(SlotPadding, SlotPadding)
        layout1.SortOrder = Enum.SortOrder.LayoutOrder
        layout1.Parent = invGrid

        local playerSlots = {}
        for i = 1, SlotCount do
            local slot = createSlot(invGrid)
            slot.LayoutOrder = i
            playerSlots[i] = slot
        end

        local personalLabel = createSectionHeader('Personal Chest', window)
        local personalGrid = Instance.new('Frame')
        personalGrid.Name = 'PersonalItems'
        personalGrid.Size = UDim2.new(1, -28, 0, 0)
        personalGrid.BackgroundTransparency = 1
        personalGrid.Parent = window
        local layout2 = Instance.new('UIGridLayout')
        layout2.CellSize = UDim2.fromOffset(SlotSize, SlotSize)
        layout2.CellPadding = UDim2.fromOffset(SlotPadding, SlotPadding)
        layout2.SortOrder = Enum.SortOrder.LayoutOrder
        layout2.Parent = personalGrid

        local playerPersonalSlots = {}
        for i = 1, PersonalSlotCount do
            local slot = createSlot(personalGrid)
            slot.LayoutOrder = i
            playerPersonalSlots[i] = slot
        end

        local armordivider = Instance.new('Frame')
        armordivider.Name = 'ArmorDivider'
        armordivider.Size = UDim2.new(1, 0, 0, 1)
        armordivider.BackgroundColor3 = color.Light(uipallet.Main, 0.04)
        armordivider.BorderSizePixel = 0
        armordivider.Parent = window

        local armorholder = Instance.new('Frame')
        armorholder.Name = 'Armor'
        armorholder.Size = UDim2.new(1, -8, 0, SlotSize)
        armorholder.BackgroundTransparency = 1
        armorholder.Parent = window
        local armorlayout = Instance.new('UIListLayout')
        armorlayout.FillDirection = Enum.FillDirection.Horizontal
        armorlayout.Padding = UDim.new(0, SlotPadding)
        armorlayout.Parent = armorholder

        local playerArmorSlots = {}
        for i = 1, 4 do
            local slot = createSlot(armorholder)
            slot.LayoutOrder = i
            playerArmorSlots[i] = slot
        end

        return {
            window = window,
            headshot = headshot,
            nametag = nametag,
            invLabel = invLabel,
            invGrid = invGrid,
            personalLabel = personalLabel,
            personalGrid = personalGrid,
            armordivider = armordivider,
            armorholder = armorholder,
            slots = playerSlots,
            personalslots = playerPersonalSlots,
            armorslots = playerArmorSlots,
            priorityStroke = priorityStroke
        }
    end

    local function setSlot(slot, item, highlight)
        if not item or not item.itemType then
            slot.Visible = false
            return
        end

        slot.Visible = true
        slot.Icon.Image = bedwars.getIcon(item, true)
        slot.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or ''
        slot.UIStroke.Color = highlight and Color3.fromHSV(Color.Hue, Color.Sat, Color.Value) or color.Light(uipallet.Main, 0.034)
    end

    local function getTarget()
        local best, highest = nil, tick()
        for ent, expiry in targetinfo.Targets do
            if expiry < tick() then
                targetinfo.Targets[ent] = nil
                continue
            end
            if expiry > highest then
                best, highest = ent, expiry
            end
        end
        return best
    end

    local function getPlayerDistance(player)
        if not player or not player.Character or not player.Character:FindFirstChild('HumanoidRootPart') then
            return math.huge
        end
        local lplrChar = lplr.Character
        if not lplrChar or not lplrChar:FindFirstChild('HumanoidRootPart') then
            return math.huge
        end
        return (player.Character.HumanoidRootPart.Position - lplrChar.HumanoidRootPart.Position).Magnitude
    end

    local function refreshWindow(playerData, isTarget)
        local player = playerData.player
        local windowData = playerData.windowData
        local inventory = store.inventories[player] or {items = {}, armor = {}}
        local hand = inventory.hand

        local currentY = HeaderHeight + 8

        windowData.nametag.Text = player.DisplayName
        windowData.headshot.Image = 'rbxthumb://type=AvatarHeadShot&id=' .. player.UserId .. '&w=420&h=420'

        ---------------------------------------------------------
        -- INVENTORY
        ---------------------------------------------------------
        local shownInventory = 0
        for i, slot in windowData.slots do
            local item = inventory.items and inventory.items[i]
            setSlot(slot, item, item and hand and item.tool == hand.tool)
            if slot.Visible then
                shownInventory = i
            end
        end

        windowData.invLabel.Visible = true
        windowData.invLabel.Position = UDim2.fromOffset(10, currentY)
        currentY += 12

        local invRows = math.max(math.ceil(shownInventory / Columns), 1)
        local invGridHeight = (invRows * SlotSize) + ((invRows - 1) * SlotPadding)
        windowData.invGrid.Position = UDim2.fromOffset(10, currentY)
        windowData.invGrid.Size = UDim2.new(1, -20, 0, invGridHeight)
        currentY += invGridHeight + 6

        ---------------------------------------------------------
        -- PERSONAL CHEST
        ---------------------------------------------------------
        local personalFolder = replicatedStorage:FindFirstChild('Inventories')
        personalFolder = personalFolder and personalFolder:FindFirstChild(player.Name .. '_personal') or nil

        local personalItems = {}
        if personalFolder then
            for _, item in personalFolder:GetChildren() do
                if item:IsA('Accessory') or item:IsA('Tool') or item:IsA('Folder') then
                    local amount = item:GetAttribute('Amount') or 1
                    table.insert(personalItems, {itemType = item.Name, amount = amount})
                end
            end
        end

        local shownPersonal = 0
        for i, slot in windowData.personalslots do
            local item = personalItems[i]
            setSlot(slot, item, false)
            if slot.Visible then
                shownPersonal = i
            end
        end

        if #personalItems > 0 or Empty.Enabled then
            windowData.personalLabel.Visible = true
            windowData.personalGrid.Visible = true
            windowData.personalLabel.Position = UDim2.fromOffset(10, currentY)
            currentY += 12

            local personalRows = math.max(math.ceil(shownPersonal / Columns), 1)
            local personalGridHeight = (personalRows * SlotSize) + ((personalRows - 1) * SlotPadding)
            windowData.personalGrid.Position = UDim2.fromOffset(10, currentY)
            windowData.personalGrid.Size = UDim2.new(1, -20, 0, personalGridHeight)
            currentY += personalGridHeight + 6
        else
            windowData.personalLabel.Visible = false
            windowData.personalGrid.Visible = false
        end

        ---------------------------------------------------------
        -- ARMOR
        ---------------------------------------------------------
        if false then -- Armor disabled
            windowData.armordivider.Visible = true
            windowData.armorholder.Visible = true
            windowData.armordivider.Position = UDim2.fromOffset(0, currentY - 1)

            for i = 1, 3 do
                local item = inventory.armor[i + 3]
                setSlot(windowData.armorslots[i], item)
            end
            setSlot(windowData.armorslots[4], hand, true)

            windowData.armorholder.Position = UDim2.fromOffset(10, currentY + 7)
            currentY += SlotSize + 15
        else
            windowData.armordivider.Visible = false
            windowData.armorholder.Visible = false
        end

        windowData.window.Size = UDim2.fromOffset(WindowWidth, currentY)
        windowData.window.Visible = true
    end

    local function refresh()
        local targetEnt = getTarget()
        local targetPlayer = targetEnt and targetEnt.Player or nil

        -- Collect all valid players
        local validPlayers = {}
        for _, player in game:GetService('Players'):GetPlayers() do
            if player ~= lplr and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
                table.insert(validPlayers, player)
            end
        end

        -- Sort by distance (target first, then by distance)
        table.sort(validPlayers, function(a, b)
            local aIsTarget = a == targetPlayer and 1 or 0
            local bIsTarget = b == targetPlayer and 1 or 0
            if aIsTarget ~= bIsTarget then
                return aIsTarget > bIsTarget
            end
            return getPlayerDistance(a) < getPlayerDistance(b)
        end)

        -- Update or create windows
        local currentY = 75
        for i, player in validPlayers do
            if not playerWindows[player] then
                playerWindows[player] = buildWindow(player)
                table.insert(windows, playerWindows[player])
            end

            local windowData = playerWindows[player]
            local isPriority = player == targetPlayer or i == 1 -- First in sorted list is highest priority
            refreshWindow({player = player, windowData = windowData}, isPriority)
            
            -- Show outline for priority target
            if isPriority then
                windowData.priorityStroke.Transparency = 0
            else
                windowData.priorityStroke.Transparency = 1
            end
            
            windowData.window.Position = UDim2.fromOffset(14, currentY)
            windowData.window.Visible = true
            currentY += windowData.window.Size.Y.Offset + WindowSpacing
        end

        -- Hide windows for players no longer in game
        for player, windowData in pairs(playerWindows) do
            if not table.find(validPlayers, player) then
                windowData.window.Visible = false
            end
        end
    end
    
    InventoryESP = vape.Categories.Inventory:CreateModule({
        Name = 'InventoryESP',
        Function = function(callback)
            if callback then
                repeat
                    if vape.ThreadFix then
                        setthreadidentity(8)
                    end
                    refresh()
                    task.wait(0.1)
                until not InventoryESP.Enabled
    
                for _, windowData in windows do
                    windowData.window.Visible = false
                end
            else
                for _, windowData in windows do
                    windowData.window.Visible = false
                end
            end
        end,
        Tooltip = 'Shows the inventory and personal chest of all enemy players. Targeted player displayed first.'
    })
    Empty = InventoryESP:CreateToggle({
        Name = 'Show without data',
        Tooltip = 'Keeps the panel up when the server has not shared their inventory yet'
    })
    Color = InventoryESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, windowData in windows do
                if windowData.window then
                    windowData.window.BackgroundColor3 = uipallet.Main
                    windowData.window.BackgroundTransparency = 1 - opacity
                end
            end
        end
    })
end)

