run(function()
    local DronePhase
    local modified = {}

    DronePhase = vape.Categories.Kits:CreateModule({
        Name = 'DroneCollision',
        Function = function(callback)
            if callback then
                local lastDroneScan = 0
                DronePhase:Clean(runService.Stepped:Connect(function()
                    local now = os.clock()
                    if now - lastDroneScan < 0.25 then return end
                    lastDroneScan = now
                    local myDrone
                    for _, drone in collectionService:GetTagged('Drone') do
                        if drone:GetAttribute('PlayerUserId') == lplr.UserId then
                            myDrone = drone
                            break
                        end
                    end

                    for part in modified do
                        if not myDrone or not part:IsDescendantOf(myDrone) then
                            modified[part] = nil
                            part.CanCollide = true
                        end
                    end

                    if myDrone then
                        for _, part in myDrone:GetDescendants() do
                            if part:IsA('BasePart') and part.CanCollide then
                                modified[part] = true
                                part.CanCollide = false
                            end
                        end
                    end
                end))
            else
                for part in modified do
                    part.CanCollide = true
                end
                table.clear(modified)
            end
        end,
        Tooltip = 'turns off collision for your ugly drone',
    })
end)

run(function()
	local AutoMetal
	local Limit
	local StreamerMode
	local Duration
	local Range
	local Animation
	
	local Legit = getFunctionRange(bedwars.HiddenMetalController.onKitLocalActivated) or 0
	local cooldowns = {}
	
	AutoMetal = vape.Categories.Kits:CreateModule({
		Name = 'AutoMetal',
		Function = function(call)
			if call then
				AutoMetal:Clean(proximityPromptService.PromptShown:Connect(function(prompt)
					if StreamerMode.Enabled and prompt.Name == 'hidden-metal-prompt' and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == 'metal_detector') then
						task.wait(0.1)
						prompt:InputHoldBegin()
					end
				end))
	
				repeat
					if not StreamerMode.Enabled and entitylib.isAlive then
						local localPosition = entitylib.character.RootPart.Position
						for _, v in collectionService:GetTagged('hidden-metal') do
							if tick() > (cooldowns[v] or 0) and (localPosition - v.Part.Position).Magnitude <= Range.Value and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == 'metal_detector') then
								if Duration.Value > 0 then
									task.wait(Duration.Value)
								end
	
								if (localPosition - v.Part.Position).Magnitude <= Range.Value then
									if Animation.Enabled then
										bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.SHOVEL_DIG)
										bedwars.AudioManager:playAudio(bedwars.SoundList.SNAP_TRAP_CONSUME_MARK)
									end
	
									bedwars.Handler:Get('CollectCollectableEntity'):Fire('SendToServer', {
										id = v:GetAttribute('Id')
									})
									cooldowns[v] = tick() + 1
								end
							end
						end
					end
					task.wait(0.1)
				until not AutoMetal.Enabled
			else
				table.clear(cooldowns)
			end
		end,
		Tooltip = 'Automatically uses the metal kit'
	})
	Limit = AutoMetal:CreateToggle({Name = 'Limit to item'})
	
	StreamerMode = AutoMetal:CreateToggle({
		Name = 'Streamer mode',
		Function = function(call)
			if Duration then
				Duration.Object.Visible = not call
				Range.Object.Visible = not call
				Animation.Object.Visible = not call
			end
		end,
		Tooltip = 'Actually does the metal prompt thing for you'
	})
	Animation = AutoMetal:CreateToggle({
		Name = 'Animation',
		Default = true,
		Tooltip = 'Plays the metal collect animation'
	})
	Range = AutoMetal:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 20,
		Default = Legit,
		Suffix = function(val)
			return val > 1 and 'studs' or 'stud'
		end
	})
	AutoMetal:CreateButton({
		Name = 'Sync to legit range',
		Function = function()
			Range:SetValue(Legit)
		end
	})
	Duration = AutoMetal:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.2,
		Decimal = 5,
		Suffix = function(val)
			return val > 1 and 'secs' or 'sec'
		end
	})
end)

run(function()
    local StorageESP
    local Background
    local Color = {}
    local Reference = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    
    local function refreshAdornee(v)
        local chest = v.Adornee:FindFirstChild('ChestFolderValue')
        chest = chest and chest.Value or nil
        if not chest then
            v.Enabled = false
            return
        end
    
        local chestitems = chest and chest:GetChildren() or {}
        for _, obj in v.Frame:GetChildren() do
            if obj:IsA('Frame') and obj.Name ~= 'UIListLayout' and obj.Name ~= 'UICorner' then
                obj:Destroy()
            end
        end
    
        v.Enabled = false
        local itemCounts = {}
        local order = {}
        for _, item in chestitems do
            local itemName = item.Name
            v.Enabled = true
            local count = 1
            if item:FindFirstChild("Amount") then
                count = item.Amount.Value
            elseif item:GetAttribute("Amount") then
                count = item:GetAttribute("Amount")
            elseif item:FindFirstChild("Value") then
                count = item.Value
            end
            if not itemCounts[itemName] then
                table.insert(order, itemName)
            end
            itemCounts[itemName] = (itemCounts[itemName] or 0) + count
        end
        
        for _, itemName in order do
            local totalCount = itemCounts[itemName]
            v.Enabled = true
            local container = Instance.new('Frame')
            container.Size = UDim2.fromOffset(26, 36)
            container.BackgroundTransparency = 1
            container.Parent = v.Frame
            
            local blockimage = Instance.new('ImageLabel')
            blockimage.Size = UDim2.fromOffset(24, 24)
            blockimage.Position = UDim2.new(0.5, -12, 0, 4)
            blockimage.BackgroundTransparency = 1
            blockimage.Image = bedwars.getIcon({itemType = itemName}, true)
            blockimage.Parent = container
            
            if totalCount > 1 then
                local countLabel = Instance.new('TextLabel')
                countLabel.Size = UDim2.new(1, 0, 0, 12)
                countLabel.Position = UDim2.new(0, 0, 1, -12)
                countLabel.BackgroundTransparency = 1
                countLabel.TextColor3 = Color3.new(1, 1, 1)
                countLabel.TextStrokeTransparency = 0
                countLabel.TextSize = 10
                countLabel.Font = Enum.Font.GothamBold
                countLabel.Text = tostring(totalCount)
                countLabel.Parent = container
            end
        end
        
        table.clear(chestitems)
    end
    
    local function Added(v)
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = Folder
        billboard.Name = 'chest'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(36, 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = v
        local blur = addBlur(billboard)
        blur.Visible = Background.Enabled
        local frame = Instance.new('Frame')
        frame.Size = UDim2.fromScale(1, 1)
        frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
        frame.Parent = billboard
        
        local layout = Instance.new('UIListLayout')
        layout.FillDirection = Enum.FillDirection.Horizontal
        layout.Padding = UDim.new(0, 0)
        layout.VerticalAlignment = Enum.VerticalAlignment.Center
        layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
            billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 6, 36), 36)
        end)
        layout.Parent = frame
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = frame
        Reference[v] = billboard
        
        local function setupChestListener()
            local chest = v:FindFirstChild('ChestFolderValue')
            if chest and chest.Value then
                local folderValue = chest.Value
                StorageESP:Clean(folderValue.ChildAdded:Connect(function()
                    refreshAdornee(billboard)
                end))
                StorageESP:Clean(folderValue.ChildRemoved:Connect(function()
                    refreshAdornee(billboard)
                end))
            end
        end
        
        setupChestListener()
        StorageESP:Clean(v.ChildAdded:Connect(function(child)
            if child.Name == 'ChestFolderValue' then
                task.spawn(setupChestListener)
                task.spawn(refreshAdornee, billboard)
            end
        end))
        
        task.spawn(refreshAdornee, billboard)
    end
    
    StorageESP = vape.Categories.Inventory:CreateModule({
        Name = 'TeamCrateESP',
        Function = function(callback)
            if callback then
                StorageESP:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(Added))
                for _, v in collectionService:GetTagged('chest') do
                    task.spawn(Added, v)
                end
                
                StorageESP:Clean(task.spawn(function()
                    while StorageESP.Enabled do
                        for _, billboard in Reference do
                            pcall(function()
                                refreshAdornee(billboard)
                            end)
                        end
                        task.wait(0.2)
                    end
                end))
            else
                table.clear(Reference)
                Folder:ClearAllChildren()
            end
        end,
        Tooltip = 'Displays all items tightly packed and their counts in crates in real-time'
    })
    
    Background = StorageESP:CreateToggle({
        Name = 'Background',
        Function = function(callback)
            if Color.Object then Color.Object.Visible = callback end
            for _, v in Reference do
                v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
                v.Blur.Visible = callback
            end
        end,
        Default = true
    })
    
    Color = StorageESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, v in Reference do
                v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                v.Frame.BackgroundTransparency = 1 - opacity
            end
        end,
        Darker = true
    })
end)

run(function()
	local AutoBekzat
	local Targets
	local Range
	local Delay
	local useAbilityEvent
	local sendFalconRemote
	local falconOut = false
	local lastSend = 0
	local lastStrike = 0

	task.spawn(function()
		task.wait()
		pcall(function()
			useAbilityEvent = replicatedStorage:WaitForChild('events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'):WaitForChild('useAbility')
		end)
		pcall(function()
			sendFalconRemote = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged:WaitForChild('SendFalconRequested')
		end)
	end)

	local function sendFalcon(pos)
		if useAbilityEvent then
			pcall(function() useAbilityEvent:FireServer('SEND_FALCON', {target = pos}) end)
		end
	end

	local function strikeFalcon(pos)
		if sendFalconRemote then
			pcall(function() sendFalconRemote:FireServer({strikeZoneEpicenter = pos}) end)
		end
	end

	local function recallFalcon()
		if useAbilityEvent then
			pcall(function() useAbilityEvent:FireServer('RECALL_FALCON') end)
		end
	end

	AutoBekzat = vape.Categories.Kits:CreateModule({
		Name = 'AutoBekzat',
		Function = function(callback)
			if callback then
				falconOut = false
				lastSend = 0
				lastStrike = 0
				AutoBekzat:Clean(runService.Heartbeat:Connect(function()
					if not entitylib.isAlive then return end
					local target = entitylib.AllPosition({
						Range = Range.Value,
						Part = 'RootPart',
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Limit = 1,
						Sort = sortmethods['Distance']
					})[1]

					local now = tick()
					if target and target.Character and target.RootPart then
						local exactPos = target.Character:GetPivot().Position
						if not falconOut then
							if (now - lastSend) >= 5 then
								sendFalcon(exactPos)
								falconOut = true
								lastSend = now
								lastStrike = 0
							end
						else
							if (now - lastStrike) >= Delay.Value then
								strikeFalcon(exactPos)
								lastStrike = now
							end
						end
					else
						if falconOut then
							recallFalcon()
							falconOut = false
						end
					end
				end))
			else
				if falconOut then
					recallFalcon()
					falconOut = false
				end
			end
		end,
		Tooltip = 'auto yeets ur falcon at enemies n keeps the strike right on em so it hits instant, calls it back when no ones around gng'
	})

	Targets = AutoBekzat:CreateTargets({
		Players = true,
		NPCs = true
	})

	Range = AutoBekzat:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 300,
		Default = 150,
		Suffix = 'studs'
	})

	Delay = AutoBekzat:CreateSlider({
		Name = 'Strike Delay',
		Min = 0.1,
		Max = 5,
		Default = 0.5,
		Decimal = 10,
		Suffix = 's'
	})
end)

