		upgradeRemote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("UpgradeFrostyHammer")
	end)

	AutoAdetunde = vape.Categories.Kits:CreateModule({
		Name = 'AutoAdetunde',
		Function = function(callback)
			if callback then
				AutoAdetunde:Clean(task.spawn(function()
					repeat
						if upgradeRemote and entitylib.isAlive and store.hand and store.hand.tool and store.hand.tool.Name == 'frosty_hammer' then
							local val = PriorityList.Value
							local order = {}
							for part in tostring(val):gmatch('[^>]+') do
								local trimmed = part:match('^%s*(.-)%s*$')
								if upgradeKeys[trimmed] then
									table.insert(order, upgradeKeys[trimmed])
								end
							end
							if #order > 0 then
								if upgradeIndex > #order then upgradeIndex = 1 end
								local key = order[upgradeIndex]
								pcall(function()
									upgradeRemote:InvokeServer(key)
								end)
								upgradeIndex = upgradeIndex % #order + 1
							end
						end
						task.wait(math.max(DelaySlider.Value, 0.3))
					until not AutoAdetunde.Enabled
				end))
			end
		end,
		Tooltip = 'auto upgrades the pick u chose when u got the crystals'
	})

	PriorityList = AutoAdetunde:CreateDropdown({
		Name = 'Priority',
		List = upgradeNames,
		Default = 'Strength',
	})

	DelaySlider = AutoAdetunde:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 2,
		Default = 0.3,
		Decimal = 10,
		Suffix = 's'
	})
end)

run(function()
    local AutoHeph
    local AutoRepair
    local AttackOnRepair

    local COOLDOWN = 6
    local ABILITY_NAMES = {
        'hephaestus_self_repair', 'tinker_self_repair',
        'hephaestus_repair', 'tinker_repair',
        'HEPHAESTUS_SELF_REPAIR', 'TINKER_SELF_REPAIR',
        'HEPHAESTUS_REPAIR', 'TINKER_REPAIR',
        'self_repair', 'SELF_REPAIR',
        'shield_repair', 'SHIELD_REPAIR',
        'kit_repair', 'KIT_REPAIR',
        'forge_repair', 'FORGE_REPAIR',
    }

    local repairingUntil = 0

    local function getKitShield(char)
        local best = 0
        for name, val in char:GetAttributes() do
            if name:find('Shield') and type(val) == 'number' and val > best and name ~= 'Shield_POTION' then
                best = val
            end
        end
        return best
    end

    local function discoverRepairAbilities()
        local found = {}
        pcall(function()
            local ac = bedwars.AbilityController
            for _, v in next, ac do
                if type(v) ~= 'table' then continue end
                for k in next, v do
                    if type(k) == 'string' and k:lower():find('repair') and not table.find(found, k) then
                        table.insert(found, k)
                    end
                end
            end
            for _, fn in {ac.canUseAbility, ac.useAbility, ac.getAbilityCooldown, ac.registerAbility} do
                if type(fn) ~= 'function' then continue end
                for i = 1, 40 do
                    local ok, _, val = pcall(debug.getupvalue, fn, i)
                    if not ok then break end
                    if type(val) ~= 'table' then continue end
                    for k in next, val do
                        if type(k) == 'string' and k:lower():find('repair') and not table.find(found, k) then
                            table.insert(found, k)
                        end
                    end
                end
            end
        end)
        return found
    end

    local function getCharAbilityName()
        local char = lplr.Character
        if char then
            for _, obj in {char, lplr} do
                for attrName, attrVal in obj:GetAttributes() do
                    if type(attrVal) == 'string' and attrVal:lower():find('repair') then
                        return attrVal
                    end
                end
            end
        end
        return nil
    end

    local function fireRepair()
        local ac = bedwars.AbilityController
        local names = discoverRepairAbilities()
        local charAbility = getCharAbilityName()
        if charAbility and not table.find(names, charAbility) then
            table.insert(names, 1, charAbility)
        end
        for _, n in ABILITY_NAMES do
            if not table.find(names, n) then table.insert(names, n) end
        end
        for _, name in names do
            local ok, canUse = pcall(function() return ac:canUseAbility(name) end)
            if ok and canUse then
                pcall(function() ac:useAbility(name) end)
                return true
            end
        end
        return false
    end

    local weaponConfig = nil
    pcall(function()
        local swc = bedwars.SwordController
        for _, fn in {swc.sendServerRequest, swc.swingSwordAtMouse, swc.swingSwordInRegion, swc.isClickingTooFast} do
            if type(fn) ~= 'function' then continue end
            for i = 1, 40 do
                local ok2, weapon, ok3
                local ok, _, val = pcall(debug.getupvalue, fn, i)
                if not ok then break end
                if type(val) ~= 'table' then continue end
                ok2, weapon = pcall(function() return val.Weapon end)
                if not ok2 or type(weapon) ~= 'table' then continue end
                ok3 = pcall(function() return weapon.respectAttackOverride end)
                if ok3 then weaponConfig = val return end
            end
        end
    end)

    local oldIsClickingTooFast = bedwars.SwordController.isClickingTooFast
    local syncConn = nil
    local stunConn = nil
    local charConn = nil

    local function attackUnlocked()
        if not AttackOnRepair or not AttackOnRepair.Enabled then return false end
        return tick() < repairingUntil
    end

    local function connectStunClear(char)
        if stunConn then stunConn:Disconnect() stunConn = nil end
        if not char then return end
        stunConn = char:GetAttributeChangedSignal('StunnedUntilTime'):Connect(function()
            if not attackUnlocked() then return end
            local val = char:GetAttribute('StunnedUntilTime')
            if val and val > workspace:GetServerTimeNow() then
                pcall(function() char:SetAttribute('StunnedUntilTime', 0) end)
            end
        end)
    end

    AutoHeph = vape.Categories.Kits:CreateModule({
        Name = 'AutoHeph',
        Function = function(callback)
            if callback then
                repairingUntil = 0

                bedwars.SwordController.isClickingTooFast = function(self, ...)
                    if attackUnlocked() then
                        if weaponConfig then
                            pcall(function() weaponConfig.Weapon.respectAttackOverride = false end)
                        end
                        return false
                    end
                    return oldIsClickingTooFast(self, ...)
                end

                connectStunClear(lplr.Character)
                charConn = lplr.CharacterAdded:Connect(function(char)
                    connectStunClear(char)
                end)

                pcall(function()
                    local sync = bedwars.ClientSync
                    if sync and type(sync.SwordSwing) == 'table' and type(sync.SwordSwing.setPriority) == 'function' then
                        syncConn = sync.SwordSwing:setPriority(1):Connect(function()
                            if attackUnlocked() and weaponConfig then
                                pcall(function() weaponConfig.Weapon.respectAttackOverride = false end)
                            end
                        end)
                    end
                end)

                local maxShield = 0
                local lastFired = 0
                local prevAlive = false
                local stableVal = -1
                local stableCount = 0

                repeat
                    local alive, char, current, now, cooldownLeft, needsRepair, healPoint
                    task.wait(0.1)

                    if not AutoRepair or not AutoRepair.Enabled then
                        prevAlive = false
                        continue
                    end

                    alive = entitylib.isAlive
                    if not alive then
                        maxShield = 0
                        lastFired = 0
                        prevAlive = false
                        continue
                    end

                    char = lplr.Character
                    if not char then continue end

                    current = getKitShield(char)

                    if current == stableVal then
                        stableCount = stableCount + 1
                    else
                        stableVal = current
                        stableCount = 1
                    end

                    if not prevAlive and current > 0 then
                        maxShield = current
                    elseif stableCount >= 2 and current > maxShield then
                        maxShield = current
                    end
                    prevAlive = true

                    now = tick()
                    cooldownLeft = math.max(0, COOLDOWN - (now - lastFired))
                    healPoint = maxShield * 0.5
                    needsRepair = maxShield > 0 and current <= healPoint

                    if cooldownLeft <= 0 and needsRepair then
                        if fireRepair() then
                            repairingUntil = now + 2
                            lastFired = now
                        end
                    end

                until not AutoHeph.Enabled
            else
                repairingUntil = 0
                bedwars.SwordController.isClickingTooFast = oldIsClickingTooFast
                if stunConn then stunConn:Disconnect() stunConn = nil end
                if charConn then charConn:Disconnect() charConn = nil end
                if syncConn then
                    pcall(function() syncConn:Disconnect() end)
                    syncConn = nil
                end
            end
        end,
        Tooltip = 'fixes ur heph shield by itself when it gets low so u dont gotta think about it'
    })

    AutoRepair = AutoHeph:CreateToggle({
        Name = 'Auto Repair',
        Default = true,
        Tooltip = 'turns the auto fixing on. leave this on gng'
    })

    AttackOnRepair = AutoHeph:CreateToggle({
        Name = 'Attack on Repair',
        Default = true,
        Tooltip = 'lets u keep swingin while ur shield is fixing instead of getting frozen'
    })
end)

run(function()
    local AutoWhisper
    local PlayerDropdown
    local AutoHeal
    local AutoHealSlider
    local AutoFly
    local LimitToItem
    local RefreshButton
    local running = false
    local healRunning = false
    local flyRunning = false
    local currentTarget = nil
    local currentMountedPlayer = nil
    local fallCheckTimer = 0
    local hasActivatedFly = false
    
    local function isHoldingOwlOrb()
        if not entitylib.isAlive then return false end
        
        local inventory = store.inventory
        if inventory and inventory.inventory and inventory.inventory.hand then
            local handItem = inventory.inventory.hand
            if handItem and handItem.itemType == "owl_orb" then
                return true
            end
        end
        return false
    end
    
    local function getMountedPlayer()
        local owlTarget = lplr:GetAttribute('OwlTarget')
        if owlTarget then
            return playersService:GetPlayerByUserId(owlTarget)
        end
        return nil
    end
    
    local function mountBirdToPlayer(targetPlayer)
        if not targetPlayer or not targetPlayer.Character then return false end
        
        if LimitToItem.Enabled and not isHoldingOwlOrb() then
            return false
        end
        
        local success = false
        pcall(function()
            local result = bedwars.Client:Get(remotes.SummonOwl).instance:InvokeServer(targetPlayer)
            
            if result then
            task.wait(0.05)
            
            pcall(function()
    			bedwars.Client:Get(remotes.UseAbility).instance:FireServer("SUMMON_OWL")
			end)
                
                currentMountedPlayer = targetPlayer
                success = true
            end
        end)
        
        return success
    end
    
    local function demountOwl()
        pcall(function()
            bedwars.Client:Get(remotes.UseAbility).instance:FireServer("DEACTIVE_OWL")
            
            task.wait(0.05)
            
            bedwars.Client:Get(remotes.RemoveOwl).instance:FireServer()
        end)
        
        currentMountedPlayer = nil
    end
    
    local function healTarget()
        pcall(function()
            replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility"):FireServer("OWL_HEAL")
        end)
    end
    
    local function isFalling(player)
        if not player or not player.Character or not player.Character.PrimaryPart then
            return false
        end
        
        local velocity = player.Character.PrimaryPart.AssemblyLinearVelocity.Y
        return velocity < -20
    end
    
	local voidRayParams = RaycastParams.new()
	voidRayParams.FilterType = Enum.RaycastFilterType.Blacklist
	voidRayParams.RespectCanCollide = true

	local function isAboveVoid(player)
		if not player or not player.Character or not player.Character.PrimaryPart then
			return false
		end
		
		local rayOrigin = player.Character.PrimaryPart.Position
		local rayDirection = Vector3.new(0, -1000, 0)
		
		voidRayParams.FilterDescendantsInstances = {player.Character, gameCamera}
		
		local rayResult = workspace:Raycast(rayOrigin, rayDirection, voidRayParams)
		
		if not rayResult then
			return true
		end
		
		return rayResult.Distance > 200
	end
    
    local function activateFly()
        pcall(function()
            replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility"):FireServer("OWL_LIFT")
            
            hasActivatedFly = true
            task.spawn(function()
                task.wait(85)
                hasActivatedFly = false
            end)
        end)
    end
    
    AutoWhisper = vape.Categories.Kits:CreateModule({
        Name = "AutoWhisper",
        Function = function(callback)
            running = callback
            healRunning = callback
            flyRunning = callback
            
            if callback then
                task.spawn(function()
                    while running do
                        if LimitToItem.Enabled and not isHoldingOwlOrb() then
                            task.wait(0.2)
                            continue
                        end
                        
                        local targetPlayer = playersService:FindFirstChild(PlayerDropdown.Value)
                        if targetPlayer then
                            currentTarget = targetPlayer
                            
                            local mountedTo = getMountedPlayer()
                            
                            if mountedTo ~= targetPlayer then
                                if mountedTo and mountedTo ~= targetPlayer then
                                    demountOwl()
                                    task.wait(0.3)
                                end
                                
                                if not mountedTo or mountedTo ~= targetPlayer then
                                    local success = mountBirdToPlayer(targetPlayer)
                                    if not success then
                                        task.wait(0.5)
                                    else
                                        task.wait(1)
                                    end
                                end
                            else
                                task.wait(0.5)
                            end
                        else
                            task.wait(0.5)
                        end
                    end
                end)
                
                if AutoHeal.Enabled then
                    task.spawn(function()
                        while healRunning and AutoHeal.Enabled do
                            if currentTarget then
                                local health, maxHealth = getPlayerHealth(currentTarget)
                                if health and maxHealth and maxHealth > 0 then
                                    local healthPercent = (health / maxHealth) * 100
                                    if healthPercent < AutoHealSlider.Value and healthPercent < 90 then
                                        healTarget()
                                        task.wait(8.5)
                                    end
                                end
                            end
                            
                            task.wait(0.5)
                        end
                    end)
                end
                
                if AutoFly.Enabled then
                    task.spawn(function()
                        while flyRunning and AutoFly.Enabled do
                            if currentTarget and not hasActivatedFly then
                                if isFalling(currentTarget) and isAboveVoid(currentTarget) then
                                    fallCheckTimer = fallCheckTimer + 0.1
                                    
                                    if fallCheckTimer >= 0.5 then
                                        activateFly()
                                        fallCheckTimer = 0
                                    end
                                else
                                    fallCheckTimer = 0
                                end
                            else
                                fallCheckTimer = 0
                            end
                            
                            task.wait(0.1)
                        end
                    end)
                end
                
                AutoWhisper:Clean(playersService.PlayerAdded:Connect(function()
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                end))
                
                AutoWhisper:Clean(playersService.PlayerRemoving:Connect(function(player)
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                    
                    if currentTarget == player then
                        currentTarget = nil
                        currentMountedPlayer = nil
                    end
                end))
                
                AutoWhisper:Clean(lplr:GetAttributeChangedSignal('Team'):Connect(function()
                    task.wait(0.5)
                    local newList = getTeammates(true)
                    if PlayerDropdown then
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            end
                        end
                    end
                    currentTarget = nil
                    currentMountedPlayer = nil
                    hasActivatedFly = false
                end))
                
            else
                running = false
                healRunning = false
                flyRunning = false
                currentTarget = nil
                currentMountedPlayer = nil
                hasActivatedFly = false
                fallCheckTimer = 0
            end
        end,
    })
    
    PlayerDropdown = AutoWhisper:CreateDropdown({
        Name = "Bird Target",
        List = {},
        Function = function(val)
            if val then
                local targetPlayer = playersService:FindFirstChild(val)
                if targetPlayer then
                    currentTarget = targetPlayer
                end
            end
        end,
    })
    RefreshButton = AutoWhisper:CreateButton({
        Name = "Refresh Teammates",
        Function = function()
            task.spawn(function()
                local newList = getTeammates(true)
                
                if PlayerDropdown then
                    pcall(function()
                        PlayerDropdown:Change(newList)
                        
                        if #newList > 0 then
                            if not PlayerDropdown.Value or PlayerDropdown.Value == "" or not table.find(newList, PlayerDropdown.Value) then
                                PlayerDropdown:SetValue(newList[1])
                            else
                                PlayerDropdown:SetValue(PlayerDropdown.Value)
                            end
                        end
                    end)
                end
                
                notif("AutoWhisper", string.format("teammate list (%d teammates)", #newList), 2)
            end)
        end,
    })
    
    LimitToItem = AutoWhisper:CreateToggle({
        Name = "Limit to Owl Orb",
        Default = true,
        Function = function(val)
        end,
    })

    AutoFly = AutoWhisper:CreateToggle({
        Name = "Auto Fly",
        Default = true,
        Function = function(val)
            if AutoWhisper.Enabled then
                if val then
                    flyRunning = true
                    hasActivatedFly = false
                    fallCheckTimer = 0
                    
                    task.spawn(function()
                        while flyRunning and AutoFly.Enabled do
                            if currentTarget and not hasActivatedFly then
                                if isFalling(currentTarget) and isAboveVoid(currentTarget) then
                                    fallCheckTimer = fallCheckTimer + 0.1
                                    
                                    if fallCheckTimer >= 0.5 then
                                        activateFly()
                                        fallCheckTimer = 0
                                    end
                                else
                                    fallCheckTimer = 0
                                end
                            else
                                fallCheckTimer = 0
                            end
                            
                            task.wait(0.1)
                        end
                    end)
                else
                    flyRunning = false
                    hasActivatedFly = false
                    fallCheckTimer = 0
                end
            end
        end,
    })
    
    AutoHeal = AutoWhisper:CreateToggle({
        Name = "Auto Heal",
        Default = true,
        Function = function(val)
            if AutoHealSlider and AutoHealSlider.Object then
                AutoHealSlider.Object.Visible = val
            end
            
            if AutoWhisper.Enabled then
                if val then
                    healRunning = true
                    task.spawn(function()
                        while healRunning and AutoHeal.Enabled do
                            if currentTarget then
                                local health, maxHealth = getPlayerHealth(currentTarget)
                                if not (health and maxHealth and maxHealth > 0) then task.wait(0.5) continue end
                                local healthPercent = (health / maxHealth) * 100
                                if healthPercent < AutoHealSlider.Value and healthPercent < 90 then
                                    healTarget()
                                    task.wait(8.5)
                                end
                            end
                            
                            task.wait(0.5)
                        end
                    end)
                else
                    healRunning = false
                end
            end
        end,
    })
    
    AutoHealSlider = AutoWhisper:CreateSlider({
        Name = "Heal Threshold",
        Min = 1,
        Max = 100,
        Default = 50,
        Suffix = "%",
    })
end)

run(function()
	local CogsworthExploit
	local remote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("GatherBotCollectItems")

	local bots = {}
	local conns = {}

	local function isBot(obj)
		return obj.Name == 'GatherBotBasic' or obj.Name == 'GatherBotPro'
	end

	local function trackBot(obj)
		if bots[obj] then return end
		bots[obj] = true
		local conn
		conn = obj.AncestryChanged:Connect(function()
			if not obj.Parent then
				bots[obj] = nil
				if conns[obj] then conns[obj]:Disconnect() conns[obj] = nil end
			end
		end)
		conns[obj] = conn
	end

	CogsworthExploit = vape.Categories.Kits:CreateModule({
		Name = 'CogsworthExploit',
		Tooltip = 'auto collects loot from every gather bot in the server not just yours',
		Function = function(callback)
			if callback then
				table.clear(bots)
				scanDescendants(workspace, function(obj)
					if isBot(obj) then trackBot(obj) end
				end, CogsworthExploit)
				local addedConn = workspace.DescendantAdded:Connect(function(obj)
					if isBot(obj) then trackBot(obj) end
				end)
				CogsworthExploit:Clean(addedConn)

				repeat
					for obj, _ in bots do
						if not CogsworthExploit.Enabled then break end
						pcall(function()
							remote:FireServer({
								player = lplr,
								gatherBot = obj
							})
						end)
					end
					task.wait(0.5)
				until not CogsworthExploit.Enabled

				for _, conn in conns do conn:Disconnect() end
				table.clear(conns)
				table.clear(bots)
			end
		end
	})
end)

run(function()
	local AutoZola
	local Range
	local Delay
	local soulLinkRemote
	local useAbilityRemote

	local function getRemotes()
		if not soulLinkRemote then
			pcall(function()
				soulLinkRemote = replicatedStorage:WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("AttemptSoulLink")
			end)
		end
		if not useAbilityRemote then
			pcall(function()
				useAbilityRemote = replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")
			end)
		end
	end

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until Range and Delay
			getRemotes()
			local linkedTargets = {}
			repeat
				if not entitylib.isAlive then task.wait(0.1); continue end
				local plr = entitylib.EntityPosition({
					Range = Range.Value,
					Part = "RootPart",
					Players = true,
					NPCs = true,
					Wallcheck = false
				})
				local linkCount = 0
				for _ in linkedTargets do linkCount += 1 end
				if plr and plr.Character and linkCount < 8 and soulLinkRemote then
					local char = plr.Character
					if not linkedTargets[char] then
						if useAbilityRemote then
							pcall(function() useAbilityRemote:FireServer("soul_link") end)
						end
						task.wait(0.1)
						local ok, result = pcall(function()
							return soulLinkRemote:InvokeServer(char)
						end)
						if ok and result and result.result then
							linkedTargets[char] = true
							char.AncestryChanged:Connect(function()
								if not char.Parent then
									linkedTargets[char] = nil
								end
							end)
						end
					end
				end
				task.wait(Delay.Value)
			until not AutoZola.Enabled
			linkedTargets = {}
		end)
	end

	AutoZola = vape.Categories.Kits:CreateModule({
		Name = 'AutoZola',
		Function = function(callback)
			if callback then startLoop() end
		end,
		Tooltip = 'auto soul links enemies for zola'
	})

	Range = AutoZola:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 50
	})
	Delay = AutoZola:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 2,
		Default = 0.3,
		Decimal = 10,
		Suffix = 's'
	})
end)

run(function()
	local AutoWarrior
	local Targets
	local Range
	local Delay
	local useAbilityRemote

	local function getAbilityRemote()
		if not useAbilityRemote then
			pcall(function()
				useAbilityRemote = replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")
			end)
		end
		return useAbilityRemote
	end

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until Targets and Range and Delay
			repeat
				if not entitylib.isAlive then task.wait(0.1); continue end
				local plr = entitylib.EntityPosition({
					Range = Range.Value,
					Part = 'RootPart',
					Players = Targets.Players.Enabled,
					NPCs = Targets.NPCs.Enabled,
					Wallcheck = Targets.Walls.Enabled,
					Sort = sortmethods.Distance
				})
				local grit = lplr:GetAttribute('Grit') or 0
				if plr and grit >= 100 then
					local remote = getAbilityRemote()
					if remote then
						pcall(function() remote:FireServer('warrior_strike') end)
					end
				end
				task.wait(Delay.Value)
			until not AutoWarrior.Enabled
		end)
	end

	AutoWarrior = vape.Categories.Kits:CreateModule({
		Name = 'AutoWarrior',
		Function = function(callback)
			if callback then startLoop() end
		end,
		Tooltip = 'auto strikes enemies when ur grit is full'
	})

	Targets = AutoWarrior:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Range = AutoWarrior:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 40,
		Default = 20
	})
	Delay = AutoWarrior:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 2,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's'
	})
end)

run(function()
	local AutoLasso
	local Targets
	local Range
	local Angle
	local LimitToLasso
	local ArrowCharge

	local projectileRemote = {InvokeServer = function() end}
	task.spawn(function()
		projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
	end)
	local handGunRemote = {InvokeServer = function() end}
	task.spawn(function()
		handGunRemote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("HandGunFireRequest")
	end)

	local rayCheck = RaycastParams.new()
	local lastShot = 0
	local autoLassoLoop

	local function doLasso()
		if not entitylib.isAlive then return end
		if LimitToLasso.Enabled then
			if not store.hand or not store.hand.tool or store.hand.tool.Name ~= 'lasso' then
				return
			end
		end

		if (tick() - lastShot) < FireRate.Value then return end

		local lasso = getItem('lasso')
		if not lasso then return end

		local ent = entitylib.EntityPosition({
			Range = Range.Value,
			Part = 'RootPart',
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods.Distance
		})
		if not ent then return end

		local selfpos = entitylib.character.RootPart.Position
		local localfacing = gameCamera.CFrame.LookVector * Vector3.new(1, 0, 1)
		local delta = (ent.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
		if delta.Magnitude <= 0.001 then return end
		if math.acos(math.clamp(localfacing:Dot(delta.Unit), -1, 1)) > (math.rad(Angle.Value) / 2) then return end

		local calc = prediction.SolveTrajectory(selfpos, 200, 135, ent.RootPart.Position, ent.RootPart.Velocity, workspace.Gravity, ent.Humanoid.HipHeight or 2, nil, rayCheck)
		if not calc then return end

		switchItem(lasso.tool, 0.05)

		local res = projectileRemote:InvokeServer(
			lasso.tool,
			'lasso',
			'lasso',
			selfpos,
			selfpos,
			CFrame.lookAt(selfpos, calc).LookVector * 200,
			httpService:GenerateGUID(true),
			{
				drawDurationSeconds = 1,
				shotId = httpService:GenerateGUID(false)
			},
			workspace:GetServerTimeNow() - 0.045
		)
		if res then
			lastShot = tick()
		end
	end

	local function startAutoLassoLoop()
		if autoLassoLoop then return end
		autoLassoLoop = task.spawn(function()
			while AutoLasso and AutoLasso.Enabled do
				doLasso()
				task.wait(0.05)
			end
			autoLassoLoop = nil
		end)
	end

	local function stopAutoLassoLoop()
		if autoLassoLoop then
			task.cancel(autoLassoLoop)
			autoLassoLoop = nil
		end
	end

	AutoLasso = vape.Categories.Kits:CreateModule({
		Name = 'AutoLasso',
		Function = function(callback)
			if callback then
				startAutoLassoLoop()
			else
				stopAutoLassoLoop()
			end
		end
	})

	Targets = AutoLasso:CreateTargets({Players = true})
	Range = AutoLasso:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 60,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	Angle = AutoLasso:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 120
	})
	FireRate = AutoLasso:CreateSlider({
		Name = 'Fire rate',
		Min = 0,
		Max = 15,
		Default = 10.5,
		Decimal = 10,
		Suffix = 's'
	})
	LimitToLasso = AutoLasso:CreateToggle({
		Name = 'Limit to Lasso',
		Default = false,
	})
end)

