run(function()
	local AutoEmber
	local Targets
	local Range
	local SpinCooldown
	local HoldRange = 32
	local old = 0
	local isCharging = false
	local chargeAnim, FpChargeAnim = nil,nil
	AutoEmber = vape.Categories.Kits:CreateModule({
		Name = 'AutoEmber',
		Tooltip = 'automatically uses the ember ability',
		Function = function(call)
			if call then
				repeat
					if not entitylib.isAlive and isCharging then
						isCharging = false
						bedwars.HellSaberController.animationMaid:DoCleaning()
						chargeAnim = nil
						FpChargeAnim = nil
					end
					if entitylib.isAlive then 
						local tool = getItem('infernal_saber') 
						if tool then
							local ent = entitylib.EntityPosition({
								Range = HoldRange,
								Players = Targets.Players.Enabled,
								NPCs = Targets.NPCs.Enabled,
								Part = 'RootPart'
							}) 

							if not ent then
								if isCharging then
									isCharging = false
									bedwars.HellSaberController.animationMaid:DoCleaning()
									chargeAnim = nil
									FpChargeAnim = nil
									task.wait(0.3)
									continue
								end
							end

							if ent then
								if not isCharging then
									isCharging = true
									bedwars.HellSaberController:playChargeSound(lplr)
									local animer = lplr.Character
									if animer ~= nil then
										animer = animer:FindFirstChild("Humanoid")
										if animer ~= nil then
											animer = animer:FindFirstChild("Animator")
										end
									end
									if not animer then
										isCharging = false
										task.wait(0.1)
										continue
									end
									chargeAnim = animer:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(bedwars.AnimationType.INFERNO_SWORD_CHARGE))
									chargeAnim:Play()
									chargeAnim:AdjustSpeed(1.83)
									chargeAnim:GetMarkerReachedSignal("end"):Connect(function()
										local newChargeAnim = chargeAnim
										if newChargeAnim ~= nil then
											newChargeAnim:AdjustSpeed(0)
										end
									end)
									FpChargeAnim = bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_INFERNO_SWORD_CHARGE)
									if FpChargeAnim then
										FpChargeAnim:GetMarkerReachedSignal("end"):Connect(function()
											local newFpChargeAnim = FpChargeAnim
											if newFpChargeAnim ~= nil then
												newFpChargeAnim:AdjustSpeed(0)
											end
										end)
									end
									bedwars.HellSaberController.animationMaid:GiveTask(function()
										local MaidCA1 = chargeAnim
										if MaidCA1 ~= nil then
											MaidCA1:Stop()
										end
										local MaidCA2 = chargeAnim
										if MaidCA2 ~= nil then
											MaidCA2:Destroy()
										end
										local MaidFCA1 = FpChargeAnim
										if MaidFCA1 ~= nil then
											MaidFCA1:Stop()
										end
										local MaidFCA2 = FpChargeAnim
										if MaidFCA2 ~= nil then
											MaidFCA2:Destroy()
										end
									end)
								end
								local DeltaPos = (ent.RootPart.Position - lplr.Character.HumanoidRootPart.Position).Magnitude
								if DeltaPos <= Range.Value then
									if (os.clock() - old) >= SpinCooldown.Value then
										bedwars.HellSaberController.animationMaid:DoCleaning()
										switchItem(tool)
										bedwars.Client:Get('HellBladeRelease'):SendToServer({
											chargeTime = 1 + tick() - (0.045 + (math.random() - math.random())), 
											weapon = tool,
											player = lplr
										})
										old = os.clock()
										bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_INFERNO_SWORD_SPIN)										
										isCharging = false
										
									end
								end
							end
						end
					end
					task.wait(0.03)
				until not AutoEmber.Enabled
				isCharging = false
				bedwars.HellSaberController.animationMaid:DoCleaning()
				chargeAnim = nil
				FpChargeAnim = nil 
			end
		end
	})
	Targets = AutoEmber:CreateTargets({
		Players = true,
		NPCs = false
	})
	SpinCooldown = AutoEmber:CreateSlider({
		Name = 'Spin Cooldown',
		Min = 0,
		Max = 4,
		Default = 1.12,
		Decimal = 100,
		Tooltip = 'how long it waits b4 spinning again. keep it above 0.2 or u finna get banned'
	})
	Range = AutoEmber:CreateSlider({
		Name = 'Release Range',
		Min = 1,
		Max = 22,
		Default = 22,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
end)

run(function()
    local AutoUma
    local rangeSlider
    local limitToStaff
    local playAnim
    local autoSummon
    local useHeal
    local useAttack
    local targetDrops
    local allowDiamond
    local allowEmerald

    local function findStaff()
        if limitToStaff.Enabled then
            local held = store.hand.tool
            if held and held.Name == 'spirit_staff' then
                return held, getHotbar(held)
            end
            return nil
        end

        for slot, item in pairs(store.inventory.inventory.items) do
            if item.itemType == 'spirit_staff' then
                switchItem(item, 0)
                return item, slot
            end
        end
    end

    local function getClosestDrop(origin, drops)
        local closest, shortest = nil, rangeSlider.Value + 1

        for _, drop in pairs(drops) do
            local valid = (drop.Name == 'emerald' and allowEmerald.Enabled) or (drop.Name == 'diamond' and allowDiamond.Enabled)

            if valid then
                local dist = (origin - drop.Position).Magnitude

                if dist <= shortest and not entitylib.Wallcheck(origin, drop.Position, {gameCamera, lplr.Character, drop}) then
                    closest = drop
                    shortest = dist
                end
            end
        end

        return closest
    end

    local function fireSpirit(staff, origin, targetPos, hasAttackSpirit)
        local shootFrom = origin + Vector3.new(0, 2, 0)

        local predicted = targetPos + Vector3.new(0,(origin - targetPos).Magnitude / 5, 0)

        local direction = CFrame.lookAt(origin, predicted).LookVector * 100

        local _spiritRemote = bedwars.Client:Get(remotes.FireProjectile).instance
        if _spiritRemote then
            _spiritRemote:InvokeServer(staff, nil, hasAttackSpirit and 'attack_spirit' or 'heal_spirit',shootFrom,origin,direction,httpService:GenerateGUID(),{drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)},workspace:GetServerTimeNow() - 0.045)
        end

        if playAnim.Enabled then
            bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.WIZARD_BALL_CAST )
            bedwars.SoundManager:playSound(bedwars.SoundList.SPIRIT_SUMMONER_CHANGE_AFFINITY,{})
        end
    end

	AutoUma = vape.Categories.Kits:CreateModule({
        Name = 'AutoUma',
        Tooltip = 'auto uses spirit staff usage for drops',
        Function = function(enabled)
            if not enabled then return end
            repeat
                local drops = collection('ItemDrop', AutoUma)
                local staff = findStaff()

                if staff and targetDrops.Enabled then
                    local atkCount = lplr:GetAttribute('ReadySummonedAttackSpirits') or 0
                    local healCount = lplr:GetAttribute('ReadySummonedHealSpirits') or 0

                    if autoSummon.Enabled and getItem('summon_stone') then
                        if useAttack.Enabled and atkCount < 1 then
                            bedwars.AbilityController:useAbility('summon_attack_spirit')
                        end

                        if useHeal.Enabled and healCount < 1 then
                            bedwars.AbilityController:useAbility('summon_heal_spirit')
                        end
                    end

                    if (atkCount + healCount) > 0 then
                        local root = entitylib.character.RootPart
                        if root then
                            local pos = root.Position
                            local target = getClosestDrop(pos, drops)

                            if target then
                                fireSpirit(staff, pos, target.Position, atkCount > 0)
                                task.wait(1.5)
                            end
                        end
                    end
                end

                task.wait(0.1)
            until not AutoUma.Enabled
        end
    })

    rangeSlider = AutoUma:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 80,
        Default = 50,
        Decimal = 5,
        Suffix = function(v)
            return v == 1 and 'stud' or 'studs'
        end
    })

    playAnim = AutoUma:CreateToggle({
        Name = 'Play Animation',
        Default = true
    })

    limitToStaff = AutoUma:CreateToggle({
        Name = 'Only When Holding Staff',
        Default = true
    })

    autoSummon = AutoUma:CreateToggle({
        Name = 'Auto Summon',
        Function = function(state)
            pcall(function()
                useAttack.Object.Visible = state
                useHeal.Object.Visible = state
            end)
        end
    })

    useHeal = AutoUma:CreateToggle({
        Name = 'Heal Spirit',
        Default = true,
        Visible = false,
        Darker = true
    })

    useAttack = AutoUma:CreateToggle({
        Name = 'Attack Spirit',
        Default = true,
        Visible = false,
        Darker = true
    })

    targetDrops = AutoUma:CreateToggle({
        Name = 'Target Drops',
        Default = true,
        Function = function(state)
            pcall(function()
                allowEmerald.Object.Visible = state
                allowDiamond.Object.Visible = state
            end)
        end
    })

    allowEmerald = AutoUma:CreateToggle({
        Name = 'Emerald',
        Default = true,
        Darker = true
    })

    allowDiamond = AutoUma:CreateToggle({
        Name = 'Diamond',
        Default = true,
        Darker = true
    })
end)

run(function()
    local AutoSkoll
    
    AutoSkoll = vape.Categories.Kits:CreateModule({
        Name = 'AutoSkoll',
        Function = function(callback)
            if callback then
                local replicatedStorage = game:GetService('ReplicatedStorage')
                
                local useAbilityRemote
                for _, descendant in ipairs(replicatedStorage:GetDescendants()) do
                    if descendant.Name == 'useAbility' and descendant:IsA('RemoteEvent') then
                        useAbilityRemote = descendant
                        break
                    end
                end
                
                local swordHitRemote
                for _, descendant in ipairs(replicatedStorage:GetDescendants()) do
                    if descendant.Name == 'SwordHit' and descendant:IsA('RemoteEvent') then
                        swordHitRemote = descendant
                        break
                    end
                end
                
                if not useAbilityRemote or not swordHitRemote then
                    vape:CreateNotification("AutoSkoll", "Required remotes not found!", 5)
                    return
                end
                
                local lastActivation = 0
                local oldNamecall
                oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
                    local method = getnamecallmethod()
                    if AutoSkoll.Enabled and self == swordHitRemote and method == "FireServer" then
                        if tick() - lastActivation >= 19.9 then
                            lastActivation = tick()
                            local args = {
                                [1] = "void_hunter_mark"
                            }
                            useAbilityRemote:FireServer(unpack(args))
                        end
                    end
                    return oldNamecall(self, ...)
                end)
                
                AutoSkoll:Clean(function()
                    hookmetamethod(game, "__namecall", oldNamecall)
                end)
            end
        end,
        Tooltip = 'Automatically triggers the Void Hunter ability on sword hits with a 19.9-second cooldown.'
    })
end)

run(function()
	local AutoCaitlyn
	local Mode
	local Range
	local MinHP
	local TargetPriorities
	local activeSession
	
	local function getEntity(value)
		return typeof(value) == 'Instance' and entitylib.getEntity(value) or nil
	end
	
	local function getContract(contracts, ent)
		for _, v in contracts do
			if v.target == ent.Player or v.target and v.target.Name == ent.Player.Name then
				return v
			end
		end
		return nil
	end
	
	local function getValidTargets(wallcheck)
		local targets = {}
		for _, ent in entitylib.AllPosition({
			Part = 'RootPart',
			Players = true,
			Range = Range.Value,
			Wallcheck = wallcheck
		}) do
			if not (ent.Player.Team and ent.Player.Team.Name == 'Spectators') then
				targets[ent.Player] = ent
				targets[ent.Character] = ent
			end
		end
		return targets
	end
	
	local function hasBed(session, plr)
		local suc, team = pcall(bedwars.TeamController.getPlayerTeam, bedwars.TeamController, plr)
		local teamId = suc and team and team.id or plr:GetAttribute('Team')
		if teamId == nil then
			return true
		end
	
		local cached = session.beds[teamId]
		if cached and cached[2] > tick() then
			return cached[1]
		end
	
		suc, team = pcall(bedwars.BedwarsController.getTeamBed, bedwars.BedwarsController, teamId)
		local result = not suc or team and team.Parent
		session.beds[teamId] = {result, tick() + 1}
		return result
	end
	
	local function getScore(session, contract, targets)
		local ent = targets[contract.target]
		if not ent then
			return nil
		end
	
		local health = ent.Humanoid.Health
		local distance = (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude
		local score = 30 + ((tonumber(contract.rewardValue) or 0) * 35)
		score += (1 - math.clamp(health / math.max(ent.Humanoid.MaxHealth, 1), 0, 1)) * 35
		score += math.max(1 - (distance / Range.Value), 0) * 20
	
		if health <= MinHP.Value then
			score += 20
		end
		if (session.threats[ent.Player] or 0) > tick() then
			score += 30
		end
		if ent.Character:GetAttribute('BleedSource') == lplr.UserId then
			score += 25
		end
		if not hasBed(session, ent.Player) then
			score += 20
		end
	
		local reward = contract.rewardExplanation
		if type(reward) == 'table' then
			score += (reward.assassin and 10 or 0) + (reward.kitClass and 8 or 0) + (reward.gear and 6 or 0)
		end
		return score, ent
	end
	
	local function getPriorityContract(session, contracts)
		local bounty = false
		for _, v in contracts do
			if v.rewardValue or v.rewardUpgrade then
				bounty = true
				break
			end
		end
		if not bounty then
			return nil, false
		end
	
		local targets = getValidTargets(true)
		local current, currentScore
		if session.priorityId then
			for _, v in contracts do
				if v.id == session.priorityId then
					current, currentScore = v, getScore(session, v, targets)
					break
				end
			end
		end
	
		local best, bestScore
		for _, v in contracts do
			local score = getScore(session, v, targets)
			if score and (not bestScore or score > bestScore) then
				best, bestScore = v, score
			end
		end
	
		if current and currentScore and best ~= current and bestScore < currentScore + 15 then
			best = current
		end
	
		session.priorityId = best and best.id or nil
		return best, true
	end
	
	local function getNormalContract(session, contracts)
		local hit = session.lastHit
		if hit and hit[2] > tick() then
			local ent = getValidTargets(false)[hit[1].Player]
			if ent == hit[1] then
				if Mode.Value == 'On Low' and ent.Humanoid.Health >= MinHP.Value then
					return nil
				end
				return getContract(contracts, ent)
			end
		end
	
		session.lastHit = nil
		return nil
	end
	
	local function selectContract(session, contract)
		if contract and not (session.pendingId == contract.id and session.pendingUntil > tick()) then
			bedwars.Handler:Get('BloodAssassinSelectContract'):Fire('SendToServer', {
				contractId = contract.id
			})
			session.pendingId = contract.id
			session.pendingUntil = tick() + 1
		end
	end
	
	local function updateCaitlyn(session)
		if not entitylib.isAlive or store.matchState ~= 1 or store.equippedKit ~= 'blood_assassin' then
			session.lastHit = nil
			session.pendingId = nil
			session.priorityId = nil
			return
		end
	
		local kit = bedwars.Store:getState().Kit
		if not kit or kit.activeContract then
			session.pendingId = nil
			session.priorityId = kit and kit.activeContract and kit.activeContract.id or nil
			return
		end
	
		if session.pendingId and session.pendingUntil > tick() then
			return
		end
		session.pendingId = nil
	
		local contracts = kit.availableContracts
		if not contracts or #contracts == 0 then
			return
		end
	
		local contract
		if TargetPriorities.Enabled then
			local available
			contract, available = getPriorityContract(session, contracts)
			if not available then
				contract = getNormalContract(session, contracts)
			end
		else
			session.priorityId = nil
			contract = getNormalContract(session, contracts)
		end
		selectContract(session, contract)
	end
	
	AutoCaitlyn = vape.Categories.Kits:CreateModule({
		Name = 'AutoCaitlyn',
		Function = function(callback)
			if callback then
				local session = {
					beds = {},
					nextUpdate = 0,
					pendingUntil = 0,
					threats = {}
				}
				activeSession = session
	
				AutoCaitlyn:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
					if activeSession ~= session then
						return
					end
	
					local source = getEntity(damageTable.fromEntity)
					if damageTable.entityInstance == lplr.Character and source and source.Player then
						session.threats[source.Player] = tick() + 3
					elseif damageTable.fromEntity == lplr.Character or damageTable.fromEntity == lplr then
						local victim = getEntity(damageTable.entityInstance)
						if victim then
							session.lastHit = {victim, tick() + 1}
						end
					end
				end))
	
				AutoCaitlyn:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function()
					table.clear(session.beds)
				end))
	
				AutoCaitlyn:Clean(entitylib.Events.LocalAdded:Connect(function()
					session.lastHit = nil
					session.pendingId = nil
				end))
	
				AutoCaitlyn:Clean(entitylib.Events.LocalRemoved:Connect(function()
					session.lastHit = nil
					session.pendingId = nil
					session.priorityId = nil
				end))
	
				repeat
					if tick() >= session.nextUpdate then
						session.nextUpdate = tick() + 0.2
						updateCaitlyn(session)
					end
					task.wait(0.05)
				until not AutoCaitlyn.Enabled or activeSession ~= session
	
				if activeSession == session then
					activeSession = nil
				end
			else
				activeSession = nil
			end
		end,
		Tooltip = 'Automatically assigns a player\'s contract when a specific action happens'
	})
	Mode = AutoCaitlyn:CreateDropdown({
		Name = 'Contract mode',
		List = {'On Hit', 'On Low'},
		Tooltip = 'On Hit - Contracts them whenever u start hitting them\nOn Low - When they\'re low',
		Function = function(val)
			if MinHP then
				MinHP.Object.Visible = val == 'On Low'
			end
		end,
		Default = 'On Low'
	})
	MinHP = AutoCaitlyn:CreateSlider({
		Name = 'Minimum Health',
		Tooltip = 'How low they have to be before contracting',
		Min = 1,
		Max = 100,
		Default = 30,
		Darker = true,
		Visible = false
	})
	Range = AutoCaitlyn:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 50,
		Default = 50,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	TargetPriorities = AutoCaitlyn:CreateToggle({
		Name = 'Target Priorities',
		Function = function()
			if activeSession then
				activeSession.priorityId = nil
			end
		end
	})
end)


run(function()
	local FishermanESP
	local FishNames = {
		fish_iron = "Iron Fish",
		fish_diamond = "Diamond Fish",
		fish_emerald = "Emerald Fish",
		fish_special = "Special Fish",
		fish_gold = "Gold Fish",
	}
	
	FishermanESP = vape.Categories.Kits:CreateModule({
		Name = "FishermanESP",
		Tooltip = 'shows what fish you are catching before the minigame starts',
		Function = function(callback)		
			if callback then		
				local exp = bedwars.Client:WaitFor(remotes.FishFound):expect()
				FishermanESP:Clean(exp:Connect(function(p24)
					local scl = p24.dropData
					if scl and scl.fishModel then
						local ftype = tostring(scl.fishModel) or 'fish_iron'
						local allDrops = scl.drops
						local lootParts = {}
						if allDrops then
							local totals = {}
							local order = {}
							for _, drop in ipairs(allDrops) do
								local item = tostring(drop.itemType) or 'unknown'
								local amount = tonumber(drop.amount) or 0
								if not totals[item] then
									totals[item] = 0
									table.insert(order, item)
								end
								totals[item] = totals[item] + amount
							end
							for _, item in ipairs(order) do
								table.insert(lootParts, item .. ' x' .. math.ceil(totals[item] * 1.4))
							end
						end
						local lootText = #lootParts > 0 and table.concat(lootParts, ', ') or 'unknown'
						notif('FishermanESP', 'Your fish will be ' .. FishNames[ftype] .. ' | Loot: ' .. lootText, 12)
					end
				end))
			end
		end
	})
end)

run(function()
