		Visible = AutoCast.Enabled
	})	

    ESPToggle = Fisherman:CreateToggle({
		Name = "Fisherman ESP",
		Default = false,
		Function = function(cv)
			if ESPNotifyToggle and ESPNotifyToggle.Object then ESPNotifyToggle.Object.Visible = cv end
			if Fisherman.Enabled then
				if cv then setupESP() else cleanupESP() end
			end
		end
	})

	ESPNotifyToggle = Fisherman:CreateToggle({
		Name = "Notify Loot",
		Default = true,
		Visible = false,
	})
end)

run(function()
	local AutoDavey
	local Switch
	local Break
	local Jump
	local LimitItem
	
	local old, oldAim
	
	local function canBreak()
		if not LimitItem.Enabled then return true end
		local itemmeta = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name]
		return itemmeta ~= nil and itemmeta.breakBlock ~= nil
	end
	
	local function breakCannon(block, keepLast)
		local deadline = tick() + 0.6 + (store.ping.total or 0)
		local hits = keepLast and math.max(math.ceil(getBlockHits(block, block.Position)) - 1, 0) or math.huge
	
		repeat
			if not AutoDavey.Enabled or not entitylib.isAlive or not canBreak() or hits <= 0 then return end
			if (block.Position - entitylib.character.RootPart.Position).Magnitude > 30 then return end
			bedwars.breakBlock(block, true, true, nil, Switch.Enabled)
			hits -= 1
			task.wait(0.1)
		until not block.Parent or tick() > deadline
	end
	
	AutoDavey = vape.Categories.Kits:CreateModule({
		Name = 'AutoDavey',
		Function = function(callback)
			if callback then
				oldAim = bedwars.CannonController.startAiming
				bedwars.CannonController.startAiming = function(self, block, ...)
					local call = oldAim(self, block, ...)
	
					if Break.Enabled and block and block.Parent and entitylib.isAlive and canBreak() and getBlockHits(block, block.Position) > 1 then
						task.spawn(breakCannon, block, true)
					end
	
					return call
				end
	
				old = bedwars.CannonHandController.launchSelf
				bedwars.CannonHandController.launchSelf = function(self, block, ...)
					if Break.Enabled and block and block.Parent and entitylib.isAlive and (block.Position - entitylib.character.RootPart.Position).Magnitude <= 30 and canBreak() then
						pcall(breakCannon, block, true)
						task.spawn(breakCannon, block)
					end
	
					local call = old(self, block, ...)
	
					if Jump.Enabled and entitylib.isAlive then
						entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
					end
					return call
				end
			else
				bedwars.CannonHandController.launchSelf = old
				bedwars.CannonController.startAiming = oldAim
			end
		end,
		Tooltip = 'Automatically breaks cannon/jump on launch'
	})
	Jump = AutoDavey:CreateToggle({Name = 'Jump on impact'})
	
	Break = AutoDavey:CreateToggle({Name = 'Break on impact'})
	
	Switch = AutoDavey:CreateToggle({Name = 'Legit switch'})
	
	LimitItem = AutoDavey:CreateToggle({
		Name = 'Limit to items',
		Tooltip = 'Only breaks when tools are held'
	})
end)

run(function()
    local DaveyAim
    local Mode
    local Position
    local Range
    local ShowTarget
    local MaxDistance
    local VelocityMultiplier
    
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    
    local function getLaunchVelocity(delta, velocity, time)
        return (delta + Vector3.new(0, workspace.Gravity * time * time * 0.5, 0)) / time - velocity
    end
    
    local function getCannon()
        local cannons = {}
        local localPosition = entitylib.character.RootPart.Position
        for _, v in store.blocks do
            if v.Name == 'cannon' and (localPosition - v.Position).Magnitude <= Range.Value then
                table.insert(cannons, v)
            end
        end
        if #cannons > 1 then
            table.sort(cannons, function(a, b)
                return (localPosition - a.Position).Magnitude < (localPosition - b.Position).Magnitude
            end)
        end
        return cannons[1] or nil
    end

    local function isMyCannon(block)
        if not block then return false end
        local lplr = game:GetService("Players").LocalPlayer
        if not lplr then return false end

        local placedBy = block:GetAttribute("PlacedBy") or block:GetAttribute("Placer") or block:GetAttribute("Owner")
        if placedBy then
            return placedBy == lplr.Name or placedBy == lplr.UserId
        end

        if bedwars.BlockController and bedwars.BlockController:getStore() then
            local blockData = bedwars.BlockController:getStore():getBlockData(block.Position)
            if blockData and blockData.placedBy then
                return blockData.placedBy == lplr.UserId or blockData.placedBy == lplr.Name
            end
        end

        return true
    end

    local function isPathBlocked(origin, velocity, time)
        local previous = origin
    
        for i = 1, 11 do
            local elapsed = time * i / 12
            local point = origin + velocity * elapsed - Vector3.new(0, workspace.Gravity * elapsed * elapsed * 0.5, 0)
            if workspace:Spherecast(previous, 2, point - previous, rayCheck) then
                return true
            end
            previous = point
        end
    
        return false
    end
    
    local function getLaunchTime(origin, delta, velocity, ceiling)
        local low, up = 0.0001, 20
    
        for _ = 1, 50 do
            local first, second = low + (up - low) / 3, up - (up - low) / 3
            if getLaunchVelocity(delta, velocity, first).Magnitude < getLaunchVelocity(delta, velocity, second).Magnitude then
                up = second
            else
                low = first
            end
        end
    
        local middle = (low + up) / 2
        if getLaunchVelocity(delta, velocity, middle).Magnitude > ceiling then return end
        if not isPathBlocked(origin, getLaunchVelocity(delta, Vector3.zero, middle), middle) then return middle end
    
        for i = 1, 20 do
            for _, time in {middle * (1 + i * 0.15), middle * (1 - i * 0.045)} do
                if getLaunchVelocity(delta, Vector3.zero, time).Magnitude <= ceiling and not isPathBlocked(origin, getLaunchVelocity(delta, Vector3.zero, time), time) then
                    return time
                end
            end
        end
    
        return middle
    end
    
    local function makeVisual(target, blockPosition)
        local part = Instance.new('Part')
        part.Size = Vector3.new(3, 3, 3)
        part.CFrame = CFrame.new(blockPosition)
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.CastShadow = false
        part.Transparency = 1
        local selection = Instance.new('SelectionBox')
        selection.Adornee = part
        selection.LineThickness = 0.04
        selection.Color3 = Color3.new(1, 1, 1)
        selection.SurfaceColor3 = Color3.new(1, 1, 1)
        selection.SurfaceTransparency = 0.75
        selection.Parent = part
        local tagSize = getfontsize('Landing (000 studs)', 14, uipallet.Font, Vector2.new(100000, 100000))
        local billboard = Instance.new('BillboardGui')
        billboard.Name = 'Tag'
        billboard.Size = UDim2.fromOffset(tagSize.X + 8, tagSize.Y + 7)
        billboard.StudsOffsetWorldSpace = (target - blockPosition) + Vector3.new(0, 2, 0)
        billboard.AlwaysOnTop = true
        billboard.Parent = part
        local tag = Instance.new('TextLabel')
        tag.Size = billboard.Size
        tag.BackgroundColor3 = Color3.new()
        tag.BackgroundTransparency = 0.5
        tag.BorderSizePixel = 0
        tag.RichText = true
        tag.FontFace = uipallet.Font
        tag.TextSize = 14
        tag.TextColor3 = Color3.new(1, 1, 1)
        tag.Parent = billboard
        bedwars.QueryUtil:setQueryIgnored(part, true)
        part.Parent = gameCamera
        return part
    end
    
    local function aimCannon(cannon, direction)
        local blockPosition = bedwars.BlockController:getBlockPosition(cannon.Position)
        local aimed
        local timeout = tick() + 1
    
        repeat
            bedwars.Handler:Get('AimCannon'):Fire('SendToServer', {
                cannonBlockPos = blockPosition,
                lookVector = direction
            })
            task.wait(0.15)
            local look = cannon:GetAttribute('LookVector')
            aimed = look and (look - direction).Magnitude < 0.0001
        until aimed or tick() > timeout or not cannon.Parent
    
        return aimed
    end
    
    DaveyAim = vape.Categories.Kits:CreateModule({
        Name = 'DaveyAim',
        Function = function(callback)
            if callback then
                DaveyAim:Toggle()
                if not entitylib.isAlive then return end
    
                local cannon = getCannon()
                if not cannon then
                    notif('DaveyAim', 'No cannon in range.', 5, 'warning')
                    return
                end

                local mouseRay = cloneref(lplr:GetMouse()).UnitRay
                local origin = Position.Value == 'Camera' and gameCamera.CFrame.Position or mouseRay.Origin
                local direction = Position.Value == 'Camera' and gameCamera.CFrame.LookVector or mouseRay.Direction
                rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, cannon}
                local ray = workspace:Raycast(origin, direction * 10000, rayCheck)
                if not ray then
                    notif('DaveyAim', 'No position found.', 5, 'warning')
                    return
                end
    
                local localPosition = entitylib.character.RootPart.Position
                local rawTarget = ray.Position + Vector3.new(0, entitylib.character.HipHeight, 0)
                local distance = (rawTarget - localPosition).Magnitude
                local target = rawTarget

                if distance > MaxDistance.Value then
                    local clampedDirection = (rawTarget - localPosition).Unit
                    target = localPosition + (clampedDirection * MaxDistance.Value)
                end

                local velocity = entitylib.character.RootPart.AssemblyLinearVelocity * (VelocityMultiplier and VelocityMultiplier.Value or 1)
                local time = getLaunchTime(localPosition, target - localPosition, velocity, math.sqrt(520 * workspace.Gravity))
                if not time then
                    notif('DaveyAim', `Out of cannon range ({math.floor((target - localPosition).Magnitude)} studs away, 500 max).`, 5, 'warning')
                    return
                end
    
                local launchDirection = getLaunchVelocity(target - localPosition, velocity, time).Unit
                local blockPosition = bedwars.BlockController:getBlockPosition(cannon.Position)
                local visual = ShowTarget.Enabled and makeVisual(target, roundPos(ray.Position - ray.Normal * 1.5)) or nil
                if visual then
                    visual.Tag.TextLabel.Text = `Landing ({math.floor((target - localPosition).Magnitude)} studs)`
                end
    
                if Mode.Value == 'Aim And Launch' then
                    cannon.AimPrompt:InputHoldBegin()
                    task.wait(cannon.AimPrompt.HoldDuration)
    
                    local timeout = tick() + 0.3
                    repeat
                        gameCamera.CFrame = gameCamera.CFrame:Lerp(CFrame.lookAt(gameCamera.CFrame.Position, gameCamera.CFrame.Position + launchDirection), 22 * runService.PostSimulation:Wait())
                        bedwars.Handler:Get('AimCannon'):Fire('SendToServer', {
                            cannonBlockPos = blockPosition,
                            lookVector = gameCamera.CFrame.LookVector
                        })
                    until tick() > timeout
                end
    
                if not aimCannon(cannon, launchDirection) then
                    notif('DaveyAim', 'Cannon refused the aim.', 5, 'warning')
                    if visual then
                        visual:Destroy()
                    end
                    return
                end

                if Mode.Value == 'Aim Only' then
                    if visual then
                        task.delay(2, function()
                            if visual then visual:Destroy() end
                        end)
                    end
                    return
                end

                if Mode.Value == 'Aim And Launch' then
                    cannon.StopAimingPrompt:InputHoldBegin()
                end
                task.wait((cannon.StopAimingPrompt.HoldDuration + 0.2) + runService.PostSimulation:Wait())
    
                if Mode.Value == 'Aim And Launch' then
                    cannon.LaunchSelfPrompt:InputHoldBegin()
                    task.wait(cannon.LaunchSelfPrompt.HoldDuration + runService.PostSimulation:Wait())
                else
                    bedwars.CannonHandController:launchSelf(cannon)
                end

                local landing = tick() + time
                local root
                repeat
                    runService.PreSimulation:Wait()
                    root = entitylib.isAlive and entitylib.character.RootPart
                    if root then
                        local remaining = landing - tick()
                        if remaining > 0.1 then
                            root.AssemblyLinearVelocity = getLaunchVelocity(target - root.Position, Vector3.zero, remaining)
                        end
                        if visual then
                            visual.Tag.TextLabel.Text = `Landing ({math.floor((target - root.Position).Magnitude)} studs)`
                        end
                    end
                until not root or tick() > landing
    
                if visual then
                    visual:Destroy()
                end
            end
        end,
        Tooltip = 'Aims a nearby cannon at your cursor and launches you onto it'
    })

    Mode = DaveyAim:CreateDropdown({
        Name = 'Aim Mode',
        List = {'Aim And Launch', 'Aim Only'},
        Default = 'Aim And Launch'
    })
    Position = DaveyAim:CreateDropdown({
        Name = 'Position Mode',
        List = {'Mouse', 'Camera'},
        Default = 'Mouse'
    })
    Range = DaveyAim:CreateSlider({
        Name = 'Search Range',
        Min = 1,
        Max = 18,
        Default = 10,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end
    })
    MaxDistance = DaveyAim:CreateSlider({
        Name = 'Max Distance',
        Min = 10,
        Max = 300,
        Default = 300,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end,
        Tooltip = 'Clamps the maximum targeting distance to avoid going past this limit'
    })
    VelocityMultiplier = DaveyAim:CreateSlider({
        Name = 'Velocity Multiplier',
        Min = 0,
        Max = 2,
        Default = 1,
        Decimal = 10,
        Tooltip = 'Adjusts player velocity factor in trajectory calculations'
    })
    ShowTarget = DaveyAim:CreateToggle({
        Name = 'Show Target',
        Default = true,
        Tooltip = 'Highlights the block you are landing on until you land'
    })
end)

run(function()
	local FalconAura
	local Range
	local Delay
	local Recall
	local nextSend = 0
	
	FalconAura = vape.Categories.Kits:CreateModule({
		Name = 'AutoBekzat',
		Function = function(callback)
			if callback then
				nextSend = 0
	
				repeat
					if entitylib.isAlive and store.equippedKit == 'falconer' and tick() >= nextSend then
						local target = entitylib.EntityPosition({
							Origin = entitylib.character.RootPart.Position,
							Range = Range.Value,
							Part = 'RootPart',
							Players = true,
							Wallcheck = true
						})
	
						if target and bedwars.AbilityController:canUseAbility('SEND_FALCON', {disableBlockedAbilityAlert = true}) then
							nextSend = tick() + Delay.Value
							bedwars.AbilityController:useAbility('SEND_FALCON')
						elseif not target and Recall.Enabled and bedwars.AbilityController:canUseAbility('RECALL_FALCON', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('RECALL_FALCON')
						end
					end
					task.wait(0.1)
				until not FalconAura.Enabled
			end
		end,
		Tooltip = 'Automatically sends Bekzat falcon at whoever is near you'
	})
	Range = FalconAura:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 150,
		Default = 80,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	Delay = FalconAura:CreateSlider({
		Name = 'Delay',
		Min = 0.1,
		Max = 5,
		Default = 1,
		Decimal = 10,
		Suffix = function(val)
			return val <= 1 and 'sec' or 'secs'
		end
	})
	Recall = FalconAura:CreateToggle({
		Name = 'Recall when clear',
		Default = true,
		Tooltip = 'Calls the falcon back once nobody is in range'
	})
end)

run(function()
	local OverlayEditor
	local FillColor
	local OutlineColor
	local Thickness
	local Animate
	local Speed
	local overlay, overlayBox, overlayTween
	local activePart
	
	local isOverlayPart = function(part)
		return part:IsA('BasePart') and part.Anchored and part.Transparency == 1 and part:FindFirstChildOfClass('SelectionBox') ~= nil
	end
	
	local function hideOverlay()
		if overlayTween then
			overlayTween:Cancel()
			overlayTween = nil
		end
		if overlay then
			overlay.Parent = nil
		end
	end
	
	local moveOverlay = function(part)
		if not overlay then return end
	
		if overlayTween then
			overlayTween:Cancel()
			overlayTween = nil
		end
	
		if Animate.Enabled and overlay.Parent == gameCamera then
			overlayTween = tweenService:Create(overlay, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = part.CFrame, Size = part.Size})
			overlayTween:Play()
		else
			overlay.CFrame = part.CFrame
			overlay.Size = part.Size
			overlay.Parent = gameCamera
		end
	end
	
	local bindPart = function(part)
		if not OverlayEditor.Enabled or not isOverlayPart(part) then return end
	
		part:FindFirstChildOfClass('SelectionBox').Visible = false
		activePart = part
		moveOverlay(part)
	end
	
	OverlayEditor = vape.Categories.Render:CreateModule({
		Name = 'SelectedItemColor',
		Function = function(callback)
			if callback then
				overlay = Instance.new('Part')
				overlay.Size = Vector3.one * 3
				overlay.Anchored = true
				overlay.CanCollide = false
				overlay.CanQuery = false
				overlay.CanTouch = false
				overlay.CastShadow = false
				overlay.Transparency = 1
				overlayBox = Instance.new('SelectionBox')
				overlayBox.Adornee = overlay
				overlayBox.LineThickness = Thickness.Value
				overlayBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
				overlayBox.Transparency = 1 - OutlineColor.Opacity
				overlayBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
				overlayBox.SurfaceTransparency = 1 - FillColor.Opacity
				overlayBox.Parent = overlay
				bedwars.QueryUtil:setQueryIgnored(overlay, true)
	
				for _, child in workspace:GetChildren() do
					bindPart(child)
				end
	
				OverlayEditor:Clean(workspace.ChildAdded:Connect(function(child)
					task.defer(bindPart, child)
				end))
				OverlayEditor:Clean(workspace.ChildRemoved:Connect(function(child)
					if child ~= activePart then return end
	
					activePart = nil
					task.delay(0.06, function()
						if not activePart and OverlayEditor.Enabled then
							hideOverlay()
						end
					end)
				end))
			else
				if activePart then
					local box = activePart:FindFirstChildOfClass('SelectionBox')
					if box then
						box.Visible = true
					end
					activePart = nil
				end
	
				hideOverlay()
				if overlay then
					overlay:Destroy()
					overlay, overlayBox = nil, nil
				end
			end
		end,
		Tooltip = 'Restyles the outline on the block you are aiming at'
	})
	FillColor = OverlayEditor:CreateColorSlider({
		Name = 'Fill Color',
		DefaultSat = 0,
		DefaultOpacity = 0.25,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val)
				overlayBox.SurfaceTransparency = 1 - opacity
			end
		end
	})
	OutlineColor = OverlayEditor:CreateColorSlider({
		Name = 'Outline Color',
		DefaultSat = 0,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.Color3 = Color3.fromHSV(hue, sat, val)
				overlayBox.Transparency = 1 - opacity
			end
		end
	})
	Thickness = OverlayEditor:CreateSlider({
		Name = 'Thickness',
		Min = 0.01,
		Max = 0.2,
		Default = 0.04,
		Decimal = 100,
		Function = function(value)
			if overlayBox then
				overlayBox.LineThickness = value
			end
		end
	})
	Animate = OverlayEditor:CreateToggle({
		Name = 'Animate',
		Default = true,
		Tooltip = 'Glides the overlay onto the next block instead of snapping to it'
	})
	Speed = OverlayEditor:CreateSlider({
		Name = 'Animation time',
		Min = 0.01,
		Max = 0.5,
		Default = 0.08,
		Decimal = 100,
		Suffix = 's'
	})
end)

run(function()
    local AutoWhimElement
    local DelaySlider
    
    AutoWhimElement = vape.Categories.Kits:CreateModule({
        Name = 'AutoWhimElement',
        Function = function(callback)
            if callback then
                local replicatedStorage = game:GetService('ReplicatedStorage')
                
                local spawnEvent
                local learnTomeRemote
                
                for _, descendant in ipairs(replicatedStorage:GetDescendants()) do
                    if descendant.Name == 'SpawnElementTome' and descendant:IsA('RemoteEvent') then
                        spawnEvent = descendant
                    elseif descendant.Name == 'LearnElementTome' then
                        learnTomeRemote = descendant
                    end
                end
                
                if not learnTomeRemote then
                    vape:CreateNotification("AutoWhimElement", "LearnElementTome remote not found!", 5)
                    return
                end
                
                if not spawnEvent then
                    vape:CreateNotification("AutoWhimElement", "SpawnElementTome remote event not found!", 5)
                    return
                end
                
                -- Event-driven only: Zero workspace loops, zero lag. It only runs code when the server says a tome spawns.
                AutoWhimElement:Clean(spawnEvent.OnClientEvent:Connect(function(data)
                    if not AutoWhimElement.Enabled then return end
                    if data and data.secret then
                        task.spawn(function()
                            local success, response = pcall(function()
                                if learnTomeRemote:IsA('RemoteFunction') then
                                    return learnTomeRemote:InvokeServer({ secret = data.secret })
                                else
                                    learnTomeRemote:FireServer({ secret = data.secret })
                                    return { success = true, element = "element" }
                                end
                            end)
                            
                            if success and type(response) == "table" and response.success then
                                local elementName = response.element or "element"
                                vape:CreateNotification("AutoWhimElement", "Successfully learned element: " .. tostring(elementName), 3)
                            end
                        end)
                    end
                end))
            end
        end,
        Tooltip = 'Automatically listens to SpawnElementTome and learns elements instantly without lag.'
    })
    
    DelaySlider = AutoWhimElement:CreateSlider({
        Name = 'Delay',
        Min = 0.1,
        Max = 1,
        Default = 0.4,
        Decimal = 1,
        Suffix = function(val)
            return 'seconds'
        end,
        Tooltip = 'Delay between claiming each tome'
    })
end)

run(function()
	local AutoGompy
	local AutoCollect
	local CollectRange
	local CollectDelay
	local CollectLimit
	local GhostESP
	local ESPBackground
	local ESPColor
	local ESPLimitVacuum
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local ghostIcon
	local collectionActive = false

	local collectRemote = replicatedStorage:WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("CollectCollectableEntity")

	local function isHoldingVacuum()
		return isHoldingItem({'vacuum'})
	end

	local function getGhostIcon()
		if not ghostIcon then
			ghostIcon = bedwars.getIcon({itemType = 'ghost_orb'}, true)
		end
		return ghostIcon
	end

	local function Added(obj)
		if Reference[obj] then return end
		local part = not obj:IsA('Model') and obj or obj.PrimaryPart
		if not part then return end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'ghost'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = part
		local blur = addBlur(billboard)
		blur.Visible = ESPBackground.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
		image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = getGhostIcon()
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[obj] = billboard
	end

	local function Removed(obj)
		if Reference[obj] then
			Reference[obj]:Destroy()
			Reference[obj] = nil
		end
	end

	local function setupESP()
		for _, v in collectionService:GetTagged('ghost') do
			Added(v)
		end
		AutoGompy:Clean(collectionService:GetInstanceAddedSignal('ghost'):Connect(function(v)
			if GhostESP.Enabled then Added(v) end
		end))
		AutoGompy:Clean(collectionService:GetInstanceRemovedSignal('ghost'):Connect(function(v)
			Removed(v)
		end))
		local lastUpdate = 0
		AutoGompy:Clean(runService.RenderStepped:Connect(function()
			if not GhostESP.Enabled then return end
			local now = tick()
			if now - lastUpdate < 0.1 then return end
			lastUpdate = now
			for obj, billboard in pairs(Reference) do
				if not obj or not obj.Parent then
					Removed(obj)
					continue
				end
				local shouldShow = true
				if ESPLimitVacuum.Enabled and not isHoldingVacuum() then
					shouldShow = false
				end
				billboard.Enabled = shouldShow
			end
		end))
	end

	local function startAutoCollect()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			while AutoGompy.Enabled and AutoCollect.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				if CollectLimit.Enabled and not isHoldingVacuum() then
					task.wait(0.5)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = CollectRange.Value
				for _, obj in collectionService:GetTagged('ghost') do
					if not AutoGompy.Enabled or not AutoCollect.Enabled or not collectionActive then break end
					local part = not obj:IsA('Model') and obj or obj.PrimaryPart
					if part and (localPosition - part.Position).Magnitude <= range then
						local id = obj:GetAttribute('Id') or obj:GetAttribute('id')
							or obj:GetAttribute('CollectableId') or tonumber(obj.Name:match('%d+'))
						if id then
							pcall(function() collectRemote:FireServer({ id = id }) end)
							if CollectDelay.Value > 0 then
								task.wait(CollectDelay.Value)
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	local function stopAutoCollect()
		collectionActive = false
	end

	AutoGompy = vape.Categories.Kits:CreateModule({
		Name = 'AutoGompy',
		Function = function(callback)
			if callback then
				if GhostESP.Enabled then setupESP() end
				if AutoCollect.Enabled then startAutoCollect() end
			else
				stopAutoCollect()
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'ghost stuff for gompy fr'
	})

	AutoCollect = AutoGompy:CreateToggle({
		Name = 'Auto Collect',
		Tooltip = 'grabs the ghosts for u no cap',
		Function = function(callback)
			if CollectRange and CollectRange.Object then CollectRange.Object.Visible = callback end
			if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = callback end
			if CollectLimit and CollectLimit.Object then CollectLimit.Object.Visible = callback end
			if AutoGompy.Enabled then
				if callback then startAutoCollect() else stopAutoCollect() end
			end
		end
	})
	CollectRange = AutoGompy:CreateSlider({
		Name = 'Range',
		Tooltip = 'how far it grabs ghosts gng',
		Min = 10,
		Max = 200,
		Default = 50,
		Visible = false
	})
	CollectDelay = AutoGompy:CreateSlider({
		Name = 'Delay',
		Tooltip = 'wait time between grabs',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's',
		Visible = false
	})
	CollectLimit = AutoGompy:CreateToggle({
		Name = 'Limit to Vacuum',
		Tooltip = 'only grabs ghosts when ur holding the vacuum'
	})

	GhostESP = AutoGompy:CreateToggle({
		Name = 'Ghost ESP',
		Tooltip = 'shows u where the ghosts at',
		Function = function(callback)
			if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = callback end
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and ESPBackground and ESPBackground.Enabled) end
			if ESPLimitVacuum and ESPLimitVacuum.Object then ESPLimitVacuum.Object.Visible = callback end
			if AutoGompy.Enabled then
				if callback then
					setupESP()
				else
					Folder:ClearAllChildren()
					table.clear(Reference)
				end
			end
		end
	})
	ESPBackground = AutoGompy:CreateToggle({
		Name = 'Background',
		Tooltip = 'adds a lil box behind the icon',
		Default = true,
		Function = function(callback)
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and GhostESP and GhostESP.Enabled) end
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					local blur = v:FindFirstChild('Blur')
					if blur then blur.Visible = callback end
					v.ImageLabel.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
				end
			end
		end
	})
	ESPColor = AutoGompy:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					v.ImageLabel.BackgroundTransparency = 1 - opacity
				end
			end
		end
	})
	ESPLimitVacuum = AutoGompy:CreateToggle({
		Name = 'ESP Limit to Vacuum',
		Tooltip = 'only shows ghosts when ur holding the vacuum'
	})

	task.defer(function()
		local collectOn = AutoCollect and AutoCollect.Enabled
		if CollectRange and CollectRange.Object then CollectRange.Object.Visible = collectOn end
		if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = collectOn end
		if CollectLimit and CollectLimit.Object then CollectLimit.Object.Visible = collectOn end
		local espOn = GhostESP and GhostESP.Enabled
		if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = espOn end
		if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (espOn and ESPBackground.Enabled) end
		if ESPLimitVacuum and ESPLimitVacuum.Object then ESPLimitVacuum.Object.Visible = espOn end
	end)
end)

run(function()
	local AutoSilas
	local Damage
	local Targets
	local DamageRange
	local Heal
	local HealThreshold

	local useAbilityRemote = replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")

	local function getCurrentAura()
		return lplr:GetAttribute("LeaderAuraType")
	end

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until Damage and Heal and DamageRange and HealThreshold and Targets
			repeat
				if not entitylib.isAlive then task.wait(0.1); continue end
				local hum = entitylib.character.Humanoid
				if Heal.Enabled and hum and hum.MaxHealth > 0 then
					local pct = (hum.Health / hum.MaxHealth) * 100
					if pct <= HealThreshold.Value then
						useAbilityRemote:FireServer("rebellion_shield")
						if getCurrentAura() ~= "healing" then
							useAbilityRemote:FireServer("rebellion_aura_swap")
						end
						task.wait(0.1)
						continue
					end
				end
				if Damage.Enabled then
					local plr = entitylib.EntityPosition({
						Range = DamageRange.Value,
						Part = "RootPart",
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled,
						Sort = sortmethods.Distance
					})
					if plr and getCurrentAura() ~= "damage" then
						useAbilityRemote:FireServer("rebellion_aura_swap")
						task.wait(0.1)
					end
				end
				task.wait(0.1)
			until not AutoSilas.Enabled
		end)
	end

	AutoSilas = vape.Categories.Kits:CreateModule({
		Name = 'AutoSilas',
		Function = function(callback)
			if callback then
				startLoop()
			end
		end,
		Tooltip = 'auto uses silas auras for u'
	})

	Damage = AutoSilas:CreateToggle({
		Name = 'Damage',
		Tooltip = 'swaps to damage aura when a enemy is close',
		Function = function(callback)
			if DamageRange and DamageRange.Object then DamageRange.Object.Visible = callback end
			if Targets and Targets.Object then Targets.Object.Visible = callback end
		end
	})
	Targets = AutoSilas:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	DamageRange = AutoSilas:CreateSlider({
		Name = 'Range',
		Tooltip = 'how close a enemy gotta be gng',
		Min = 1,
		Max = 50,
		Default = 14,
		Visible = false
	})

	Heal = AutoSilas:CreateToggle({
		Name = 'Heal',
		Tooltip = 'shields + heal aura when ur hp gets low',
		Function = function(callback)
			if HealThreshold and HealThreshold.Object then HealThreshold.Object.Visible = callback end
		end
	})
	HealThreshold = AutoSilas:CreateSlider({
		Name = 'HP Threshold',
		Tooltip = 'heals when ur hp drops under this',
		Min = 1,
		Max = 100,
		Default = 40,
		Suffix = '%',
		Visible = false
	})

	task.defer(function()
		if Targets and Targets.Object then Targets.Object.Visible = Damage and Damage.Enabled end
		if DamageRange and DamageRange.Object then DamageRange.Object.Visible = Damage and Damage.Enabled end
		if HealThreshold and HealThreshold.Object then HealThreshold.Object.Visible = Heal and Heal.Enabled end
	end)
end)

